window.POEM_DB=window.POEM_DB||{};POEM_DB["yuan_016"]={"n":"郑元祐","dyn":"元","poems":[{"t":"寄金山普衲","f":"七言绝句","c":["金鳌背上郁蓝天，长有神龙卫法筵。","午夜江声推月上，浪花如雪寺门前。"]},{"t":"和萨天锡留别张贞居，寄倪元镇","f":"七言律诗","c":["梁溪岁暮若为情，溪上梅花待晓晴。","径雪冷埋山屐齿，檐冰夜堕石床声。","《内篇》携向松根读，如意持将竹里行。","短晷何能理幽事？","南窗剪烛话寒更。"]},{"t":"送友还乡","f":"五言古诗","c":["堕地作男儿，有用须及早。","当年悬弧意，焉得乡曲老？","青云一蹉跎，鬓发日已皓。","常恐归去迟，心焉惄如捣。","我家东吴城，翠竹森若葆。","力耕输王税，妻子亦温饱。","诗成每独咏，觞至或共倒。","富贵将焉如？","岁晏聊自保。","萧萧风前柳，贸贸霜下草。","有官固当归，无官归亦好。"]},{"t":"芝云堂","f":"七言古诗","c":["仙家芝草晔五色，海日一照蒸成云。","结为楼观霄汉上，千门万户皆氤氲。","斑龙误骑有诵籍，云旗夜下星宫君。","忽焉随地变为石，昆吾有刀切不得。","岩壑高深翠涛积，卿云轮囷瑶草碧，永护金粟仙人宅。"]},{"t":"旌表孝义金门","f":"曲","c":["出吴东门，沄沄其水。","傅陆以居，居民栉齿。","不有孝义，众何所恃？","孝义伊何？","曰维金氏。","百五十祀，业儒循轨。","事亲养志，同气敬顺。","兄掌家钥，弟秉文印。","不矜而誉，不言而信。","里举乡推，事腾于朝。","用旌其门，以阐教条。","张书扁式，与表迩远。","守臣树声，加示庆典。","坊名孝义，大厥里门。","彰善瘅恶，周书具存。","吴固沃土，才隳于膴。","风颓俗靡，事鲜俪古。","求若孝义，几何其心？","堪继公艺，价重南金。","克孝克义，我谣我歌。","借耰阋墙，敦化猗那。"]},{"t":"高昌契侯三节堂","f":"曲","c":["惟天启契，产自辇水。","润被北庭，侯济厥美。","挺事昌朝，忠武罕比。","戡金平宋，策审功侈。","入毗庙堂，黔黎安只。","蛮酋兽犷，侯辕南指。","忠愤踊跃，奋莫顾己。","忠诚贯天，白虹触起。","孱孱孤嫠，哭侯孔哀。","誓死靡他，夫人贞哉。","贞哉夫人，夫死儿乳。","教儿能孝，父志在汝。","齿方成童，母病弗疗。","刲肱和糜，人孰儿诏？","彼美至性，移孝而忠。","抚字列城，继侯英风。","侯既有子，且复有孙。","孙皆读书，益大侯门。","相继掇科，荐承宠光。","侯其来归，英爽乐康。","子佩金符，孙萦紫绶。","世讶其隆，侯植之厚。","三节一贯，何有夷险？","恊于王风，永配令典。"]},{"t":"可斋","f":"曲","c":["大哉宣圣，以诗教我。","兴观群怨，皆与曰可。","诚笃是学，感发志意。","善善恶恶，庶全美刺。","诗人得失，于焉考见。","妍媸在已，反省毋眩。","和以处众，不至于流。","设使雷同，其道亦缪。","惩创羞恶，中惟一致。","温柔敦厚，慎勿暴气。","用以事亲，孝哉有子。","移以为忠，曾不越此。","鸟兽草木，名类匪一。","惟笃学问，旁资多识。","是我宣圣，以诗设教。","下逮百王，是则是效。","嘉子嗜学，尤勤于诗。","以可名斋，义实在兹。","六义具存，既殚源委。","以咏以歌，性情斯理。"]},{"t":"登鸿山吊梁伯鸾","f":"曲","c":["我以饥驱，爰求乐土。","居近山麓，山名孔膴。","问之父老，曰伯鸾父。","尝登兹山，览历平楚。","因以名山，义匪誇诩。","注意山栖，兹非其所。","敬吊夫子，愿嗣德音。","隼栖择高，鱼游择深。","夫子当时，五噫讴吟。","出都接浙，笑掷华簪。","归隐杵臼，佣力是任。","配谐德曜，雍雍鼓琴。","上窥羲轩，下混古今。","以乐此心，俪古傲今。","而我肱折，不知息心。","年登知命，尚浮尚沈。","圣域缅邈，世途崎崟。","矢从夫子，投迩深窅。","既齐物我，兼忘昏晓。","万里非旷，一隙非小。","毋曰昭昭，示人皦皦。","聊从兹逝，以谢胶扰。","夫子不违，罔知适从。","蝇附以骥，菟罥以松。","有薪朝炊，有稻夜砻。","式依夫子，娱老考终。","优哉悠哉，歌以相舂。"]},{"t":"兰","f":"曲","c":["恊以鼓琴，世谁知音？","采苢纫佩，湘江水深。","兰生棘中，如石轥玉。","玉受不瑳，幽香满谷。"]},{"t":"为李绎成悼其妻冯氏","f":"曲","c":["彼美者媛，令姿静淑。","姆教在鞶，懿范端肃。","择配皙士，闻望右族。","读书思荣，焚膏继晷。","媛来主馈，克承夫志。","载缉载纫，裳衣补缀。","奉飧举案，翼若始祭。","倏遭百罹，綵凤分飞。","鼓盆哭哀，语及涕洟。","人孰无妇？","妇贤而暌。","永怀弗谖，爰形声诗。"]},{"t":"春晖楼","f":"曲","c":["阳春有晖，泛在物表。","寸草承之，弗间其小。","春晖熙熙，彼草离离。","区萌就质，芃芃茂斯。","诗人载歌，悉物之情。","子于父母，恩莫与京。","亲恩之大，春阳之溥。","子心如草，肤寸思补。","爰搆重屋，以奉父母。","以介眉寿，其乐吁吁。","旨甘滫澻，奉亲之常。","寸草之微，那报春阳？","孝子爱日，孝子养志。","敬亲之枝，勿蹈非礼。","扬亲之誉，悠久不已。","是谓可报，寸草春晖。","万一攸在，吾祈与归。"]},{"t":"拟古五首 其一","f":"五言古诗","c":["北辰众星宗，列宿环共之。","斗杓指其方，生始悉所资。","万卉春芃芃，至秋悴如期。","蠢动罔弗然，辟翕启闭随。","静观造化理，在人岂其遗？","君象实有类，万古成纲维。"]},{"t":"拟古五首 其二","f":"五言古诗","c":["仲尼去云远，吾道日以微。","达士忘贱贫，佞人纷是非。","时态良弗古，乃致美事希。","末路欲忘言，屏迹避危机。","桐江有垂钓，首阳有采薇。","清风盖一世，舍此其安归？"]},{"t":"拟古五首 其三","f":"五言古诗","c":["大道本常在，为士者弗由。","穷居叹时迈，逐世竟悠悠。","豪强互吞劫，雄智复相尤。","遂令务誇诈，攘窃何时休？","所贵者仁义，势力焉足谋？","懿教信辽矣，民风此其媮。","默默掩幽室，感之纷泪流。"]},{"t":"拟古五首 其四","f":"五言律诗","c":["春来桃杏华，秋荣菊与杞。","岂但物性殊？","造化之所使。","人生类如斯，通塞固其理。","苟识吾性诚，隐显良有以。"]},{"t":"拟古五首 其五","f":"五言古诗","c":["委身竹素间，义理费考寻。","巀嶪泰华高，浩瀚沧溟深。","涉之远无津，举之力难任。","不如反诸己，求诸圣贤心。","成汤警日新，大禹惜寸阴。","纷拿试屏绝，请鼓无弦琴。","因之忘肉味，太古寥寥音。"]},{"t":"出塞七首，效少陵 其一","f":"五言律诗","c":["已踰乌盭山，未涉狐奴水。","饥羸形骸黑，枕戈待明起。","将军方蹋鞠，天地入马箠。","吾侪亦何人？","一死等蝼蚁。"]},{"t":"出塞七首，效少陵 其二","f":"五言古诗","c":["秦时闾左戍，汉家弛刑徒。","髑髅弃瀚海，天阴哭呜呜。","我非望生还，魂魄迷归途。","但愿戈矢利，委身斲狂胡。","吁嗟载笔书，不纪万骨枯。"]},{"t":"出塞七首，效少陵 其三","f":"五言古诗","c":["受诏武台宫，西遮钩营道。","阸虎射命中，相从愿深讨。","蹑血焚龙庭，以功当横草。","平沙列部伍，鲜整旄与葆。","奚虑蛇豕繁，一鼓欃枪扫。","归取万户侯，岁月未云老。"]},{"t":"出塞七首，效少陵 其四","f":"五言古诗","c":["糒吞天山雪，衣裂青海风。","前行几千里，不见单于宫。","走马脱辔头，所恃五石弓。","乡井岂不怀？","简书戒命洪。","黄尘触垒起，勇奋奔貔熊。","铅刀异莫邪，所觊一割功。"]},{"t":"出塞七首，效少陵 其五","f":"五言律诗","c":["骑羊五岁儿，出没区脱中。","翻身异鸟鼠，快捷如飞鸿。","生理不土著，水草无丰凶。","一战那足平，燕然方勒功。"]},{"t":"出塞七首，效少陵 其六","f":"五言古诗","c":["烽烟边上发，塞雁群南翔。","仰睇冥冥天，风雩雨雪霜。","驱马上崖谷，悲笳咽云黄。","弃绝骨肉亲，讵弗怀故乡？","军声动剑戟，炮火烧衣裳。","鞠育非寡恩，道远不得将。","吞咽复何愤，思虏其名王。"]},{"t":"出塞七首，效少陵 其七","f":"五言古诗","c":["边尘暮犹黑，鬼燐出霜草。","转战图报国，宁虑骨枯槁？","人生无百年，一毙不待老。","但愿土境富，微躯奚足道？","勋业铭旗常，秋天气同杳。"]},{"t":"寄张仲敏","f":"五言古诗","c":["子居阖闾城，有屋蔽风雨。","心融诗书泽，口断儿女语。","客庖妇供馔，茗灶手自鬻。","外屦多弗却，束脯乾可茹。","如何舍之去？","昼堕缘栋鼠。","朱门盍华簪，青冥无凡羽。","已随凤鸣冈，尚感雁遵渚。","于以见贞操，屯贞贵能处。"]},{"t":"仲春六日，辱陈敬初诸君枉顾，小饮敝楼，分得静字","f":"五言古诗","c":["葱肆不嗅荤，荜门惟习静。","何此枉飞佩？","诸君森相映。","方惭乏词锋，安知堕语阱？","酒杯浅于脐，楼居小如磬。","敢云谐谑欢，遂忘跪跽敬。","飞花落砚席，轻云拂麈柄。","舍坐或屡舞，分题各成咏。","莫非江海士，行应丘园聘。","顾我拓飞蓬，更春不复盛。","假如湛诚痴，何嫌宪非病？","相会苟不乐，明朝雪盈镜。"]},{"t":"赠谭台史","f":"五言古诗","c":["高昌佳公子，气横海岳秋。","玉壶洗零露，锦机濯芳洲。","真致埃壒外，独与神明游。","岧峣凤凰台，日晏行云愁。","帝念南纪大，建台分顾忧。","列圣耳目寄，职斯布皇猷。","谁工古人学？","可参宪臣谋。","之子被辟命，束书上升州。","煌煌三台星，列宿莫敢俦。","而子妙折旋，婉娈通衿喉。","不居世禄懿，远慕儒术优。","先正高与马，德言皆可雠。","骨朽名不泯，耿光悬斗牛。","子能勖令闻，席珍重天球。","况复五彩笔，尽意工冥搜。","飞花落棋局，弱柳维江舟。","感此时物佳，念子何能休？","龙驹少汗血，驽马老益羞。","白云高莫和，青山晓加稠。","日没烟树远，重倚城南楼。"]},{"t":"仙山楼观图","f":"五言古诗","c":["嵯峨三神山，仙圣之所居。","芝草布庭阙，霞光曳衣裾。","渴饮碧玉浆，饥餐紫琳腴。","霓旌冉冉下，彤楼拥鸾舆。","青童启藏室，帝命校宝书。","齐心始能读，字字皆玄枢。","朗咏以相授，灵风舞神鱼。","天远靡得闻，何以能启予？","空嗟珊瑚日，照耀金芙蕖。"]},{"t":"久旱得雨","f":"五言古诗","c":["望秋似即鹿，以旱同无虞。","忽殄蕴虫虫，屏翳腾龙鱼。","乃合霢霂雨，凉气吹髯须。","未必便滂沛，且掩羲和车。","高田土生烟，稿禾仍盼苏。","泽陂未萎稻，引根勿踌蹰。","一或荐清庙，犹与丰年俱。","忆昨岁巨浸，流潦恒满衢。","庶士宅一廛，下农田一区。","彼此灶产蛙，潭蛟为饥驱。","至今殍死鬼，夜夜哭其庐。","朅来获一饱，焉知阴惨舒？","焦原赤欲烧，政不妨官租。","民输谅有几？","廪收长有馀。","盗臣被华衮，我口何由糊？","悲歌等恸哭，激烈谁非夫？"]},{"t":"送杨郡博赴任上饶","f":"五言古诗","c":["广信山水邦，儒宫净含晖。","阴阴松桧中，白鹇时两飞。","雨馀岩泉落，清音叶鸣徽。","泮沼紫鳞跃，讲坛红杏菲。","藤蔓绕涧石，新绿罗成帏。","诸生翻经坐，子衿间褒衣。","格言咀芳润，奥理宣幽微。","凡陋当脱屣，圣哲胥乘机。","迟师一指授，仁风敞岩扉。"]},{"t":"与张天雨、杨廉夫、陈子平诸公游虎丘，次东坡韵","f":"五言古诗","c":["昔吴有悬精，兹丘据其领。","前瞻埋金竁，尚馀淬剑井。","简书畏怀异，星日发光耿。","干将不剸兕，牡鞠岂禁黾？","至今点头石，断非跃冶矿。","上机不由智，大将宁论猛？","公剖儒释绪，便从康庄聘。","词镌琬琰严，声抽辘轳哽。","掉鞅清静海，不堕生死顷。","忆昔此采游，六月佩旌冷。","山灵宝其躅，岁月尘劫永。","我生苦后时，惜此媚风景。","坐啸嗟所见，起舞顾其影。","箕尾横青天，有怀无从请。"]},{"t":"赠张生","f":"五言古诗","c":["堂堂金源公，门墙多桃李。","根柢无浅深，恩荣周远迩。","张生事公久，最为公所喜。","折旋杖屦间，唯诺图书里。","公承天子诏，驰传将使指。","宵忧泣牛衣，昼征麾马箠。","风餐邮亭庖，露炊官署米。","蹀躞趣装骑，纷纶割鲜匕。"]},{"t":"胡古愚南归","f":"五言古诗","c":["胡君有佳儿，纯悫而静者。","自君留词掖，思君不暂舍。","亲老当悬车，迎之辇毂下。","喜亲出都门，徒跣控亲马。","祖道宾迭至，别杯酒更把。","官秩司旗常，饯章宣风雅。","击节想已屡，知音谁云寡？","归途春冰泮，烧痕灵雨洒。","喜见江南山，螺黛秀而野。","挂帆胥江潮，卧听滩声泻。","儿搆远碧楼，楼成君归也。","旦旦候鹊喜，夜夜卜灯灺。","出迎空里闾，驩声振屋瓦。","妇增姑馔供，孙将儿衣扯。","整蠹理篇帙，割鲜作脯鲊。","君归乐如此，令我空蹊踝。","行乐须及时，岁冲难久假。"]},{"t":"张彦冲北上","f":"五言古诗","c":["堂堂宛丘公，高怀罗星斗。","明良之君臣，尊严之师友。","皇经在胄监，而公为祭酒。","英材资乐育，本公生物手。","麟趾瑞物呈，蚌胎明珠剖。","览辉凤凰下，击剑龙虎吼。","自非学术纯，何以服众耦？","乡公侨南纪，积学富林薮。","青天珠玑唾，一一化琼玖。","公今庙廊上，我则牛马走。","食贫苋撑肠，禦腊衣露肘。","于焉识张生，嗜学不少苟。","自言家在汳，外家读书久。","今将入成均，积分会居首。","于时中吴道，岸花杂汀柳。","风帆遂北上，解缆星在罶。","会见生去后，才名腾众口。","为拜祭酒公，桓荣汉廷叟。","上探群圣秘，下溉群物朽。","须令腐儒喜，行乐歌陇亩。"]},{"t":"送刘长洲","f":"五言古诗","c":["中吴号沃土，壮县推长洲。","秋粮四十万，民力罢诛求。","昔时兼并家，夜宴弹箜篌。","今乃呻吟声，未语泪先流。","委肉饿虎蹊，于今三十秋。","亩田昔百金，争买奋智谋。","安知徵敛急？","田祸死不休。","膏腴不论直，低洼宁望酬？","卖田复有献，惟恐不见收。","日觉乡胥肥，吏台起高楼。","坐令力本农，命轻波上沤。","天意悯困剧，南辕卯金侯。","侯有万金剂，探囊令病瘳。","躄者起雀跃，瘖者言嘲啁。","坐令百里邑，奸回息彫锼。","是皆仁侯惠，颂声满道周。","清朝考功选，赏典无滞留。","愿侯登廊庙，一洗苍生忧。"]},{"t":"松轩，为潘世谷追题其祖忠烈公卷","f":"五言古诗","c":["昔在世皇日，潘侯如贞松。","耸身青云表，流润翠百重。","迎寒保金石，遇雨翔虬龙。","枅栱夙所具，匠氏仍相逢。","一洒鼎湖泪，难进泰山封。","仁者滋有后，孙枝挺玄冬。","愿继岁寒节，雨露日以浓。"]},{"t":"高节楼","f":"五言古诗","c":["自古高节士，无如严子陵。","客星耀寒芒，归隐不可徵。","妇人守妇节，之死矢不二。","以节加今名，或顺或婉懿。","舍是而曰高，高岂在闺壸？","由名斯究实，于义窃未稳。","袁母陈氏媪，一邑称淑贤。","训儿昌家基，母老雪满颠。","岩岩高节楼，枅栱绚云日。","一赋柏舟诗，千古保贞吉。"]},{"t":"宴顾氏芝云堂，分韵得玉字","f":"五言古诗","c":["开士枉遥驾，贞人启华屋。","座接麈谈素，酒倾麟壶绿。","远山横书幌，飞花落棋局。","谷芳寄荃蕙，夕阴留梧竹。","双丝夹鹍弦，群书閟鱼目。","迹异心匪殊，语契道难渎。","接驩虽云暂，后会讵可卜？","离怀渺烟水，遐音毋金玉。"]},{"t":"过沈仲说清樾轩","f":"五言古诗","c":["眷此龙伯国，湖江白漫漫。","路出洲渚上，天垂葭苇端。","林树茂清樾，浪花浮碧澜。","烟消栋宇出，露下场圃宽。","渔师自绳擉，农老仍衣冠。","隐侯有令德，篯铿富清欢。","跫音喜人至，戟手劝客餐。","酒行鹤献舞，饮具鱼横盘。","自称礼法野，所贵人情安。","江山岁欲暮，风露日以寒。","兰佩香久歇，蒯缑铗空弹。","怀君不暂置，于世何所干？","明发当复来，寿杯为子乾。"]},{"t":"吴兴道场山","f":"五言古诗","c":["道场古名刹，浮图冠其山。","峰峦日星上，栋宇云雾间。","罗立千柱宫，欲亢九虎关。","苏公昔出守，以齿鬓未斑。","诗如九河奔，留列青崭颜。","至今作虹气，夜电锼神奸。","赵侯景苏者，水绿芙蕖殷。","公馀继笑咏，暂可抛愚顽。"]},{"t":"苏公潭","f":"五言古诗","c":["凤举不铩翮，龙腾不伤鳞。","由来贵显者，定异寻常人。","公昔令乌程，溺水已没身。","河伯急扶出，体完气仍伸。","公后践台鼎，潭名此其因。","山厚玄豹伏，水清白鸥驯。","怀公莅立处，云木青蓁蓁。","赵侯或公馀，濯缨鉴渊奫。"]},{"t":"游鸿禧废寺，听旧僧心敬言","f":"五言古诗","c":["渡南已四叶，继统属济王。","祀国支圯柱，前星掩寒芒。","帏妍肇牝晨，奴谋肆鸱张。","两潘为义激，不顾百口戕。","起以奉其主，近在苕水阳。","天津斡斗杓，海底洗日光。","人非霍狄俦，谁是涉险航？","闻其被戮时，母老两鬓霜。","吐辞语观者，令人殊激昂。","吾见宋忠臣，虽死犹不亡。","至今草间燐，荧荧出幽房。","北城鸿禧寺，栋宇自萧梁。","两潘举义日，俾众听钟撞。","哀哉城门火，遽遗池鱼殃。","遂指寺逆地，潴宫示非常。","田断饭僧粥，炉冷供佛香。","金像久颓剥，青苔重悲凉。","仰惧枅栱坠，俯叹榛莽长。","残僧四五人，饥用篾束肠。","敬也业尤白，宴坐不下堂。","家本蜀杨氏，能言寺之详。","补苴罄衣钵，创巨医难良。","更今百廿年，我来重彷徨。","潘忠世莫雪，寺废人弗伤。","天高莫之诉，题诗空慨慷。"]},{"t":"送俞漕掾","f":"五言古诗","c":["乡年子胡子，在杭客僧坊。","褐衣冷不絮，蛙灶突不炀。","直言迅风霆，劲气蟠穹苍。","独与俞校理，笑语温而庄。","心探群经奥，目短百氏墙。","折衷不求似，各极其短长。","我时为诸生，拱听私自庆。","融万会于一，掣蔀睹日光。","死生一阔别，今几四十霜。","我既为饥驱，东泛吴下航。","俞公有犹子，吏事析豪芒。","读书复读律，才比百鍊钢。","漕府多俊彦，何异雁鹜行。","秩满升帅府，年劳跻省郎。","功名晚亨奋，自可上庙堂。","我忝里闬末，看子青云翔。","威凤一高举，应龙岂终藏？","送子岁年暮，赠子金玉章。"]},{"t":"悯农，送张德常吴令出郊劝农，兼柬国瑞公相","f":"五言古诗","c":["日行底天廓，劝农正其时。","畇畇土膏动，穆穆条风吹。","渚花尚自媚，汀柳亦间垂。","中吴号沃壤，东作多遗黎。","首更太伯化，民俗恒熙熙。","一从干戈兴，杀虏令人悲。","草生髑髅眼，灶绝茅茨炊。","十室存二三，烧劫偶见遗。","官租不少贷，民力何由支？","张侯尹吴县，冰檗严矜持。","徵科泪暗落，且复鞭创痍。","兹当东作兴，载耜循年规。","言告加勉勖，心伤为嗟咨。","田老锋镝馀，仅保骨与皮。","犹复望岁丰，迎拜携孤嫠。","茹芹敢望饱？","无力堪拖犁。","嚼虱恒苦腥，饭牛恒苦饥。","侯为百里宰，腹笥盛书诗。","民劳曷小康？","民病曷小医？","虢文谏周室，千古有令仪。","咽饿啖儿肉，何人埋父尸？","民力苟不苏，天鉴亦不私。","上帝专主宰，臣言谅非痴。"]},{"t":"鹤巢，次张贞居韵","f":"五言古诗","c":["胎禽巢居迥，每在林表松。","栋梁架青冥，户牖瞰碧峰。","欲睹仙者驭，每怀尘外踪。","玉童坐吹笙，娟娟好颜容。","时归理其室，护以虎与龙。","茅檐瑶草香，欲往路莫从。","星宫集群真，霞光覆千重。","邂逅十洲上，仙圣应相逢。"]},{"t":"赋采香径，送吴县张令升佐嘉定州","f":"五言古诗","c":["泰伯常采药，深蹊入芳菲。","攀桂作帷帐，纫兰制裳衣。","坐令文身俗，悉从端委归。","支胤后世君，礼让日渐违。","迷阳行棘足，蘼芜露沾衣。","三秀不改度，斋房耀灵辉。","撷之荐瑶席，神享民是依。"]},{"t":"游惠山寺","f":"五言古诗","c":["百里尽平壤，兹山忽中蟠。","谽谺得宏深，迂徐纳平宽。","僧坊隐其腹，崇搆居桓桓。","立神卫觚棱，缘云置阑干。","我来玄冬交，榜舟起微澜。","天连黄沙白，露委青林丹。","地无车马尘，松筠政坚完。","苍然后凋意，彼此不厌看。","稍稍陟其崖，探源汲清寒。","恭惟桑苧翁，出处良独难。","帝青九万里，冥飞见脩翰。","空留雪泥迹，莫究清净观。","煮茗涤烦暑，晏然有馀欢。"]},{"t":"山雪斋","f":"五言古诗","c":["山中太始雪，玉光郁巑岏。","积之非岁月，坐而阅暑寒。","纯白既不变，空明谅非难。","悬冰松梢堕，危石涧底蟠。","维时古真人，头峨切云冠。","闵世方内热，忧喜亏其完。","燕坐以观复，一念万劫宽。","问之何因耳？","笑指青琅玕。"]},{"t":"明月镜","f":"五言古诗","c":["神工铸明镜，持进嫦娥宫。","嫦娥羞鉴容，暮挂扶桑东。","浮云散天风，照耀九海空。","如何万丈光？","泻入诗仙胸。","谈玄走银蟾，落笔惊彩虹。","掩却星斗文，孤辉天地中。"]},{"t":"上清金蓬头道者画像","f":"五言古诗","c":["巍巍龙虎山，融结自太古。","笃生虚静君，道独继祖武。","真人生岩穴，萧然一环堵。","蓬首目光炯，燕坐闻众父。","爰契虚静心，天风桧杉舞。"]},{"t":"赠姚尊师","f":"五言古诗","c":["山中学仙侣，乡来发皆玄。","惊我头白来，忽已十七年。","民物殊更变，青山独依然。","馆我太霞室，酌以松根泉。","非君慰幽独，空斋难晏眠。"]},{"t":"赠江右哲上人","f":"五言古诗","c":["江右山水窟，所产多才贤。","溢为空门秀，一一皆清妍。","向时欣太中，说法龙河壖。","遂令吴下雪，便参老晖禅。","昼飞楚畹墨，夜发升州船。","文庙日有赐，来自冥冥天。","地蒸金银气，海涌云霞鲜。","歆艳谷崖动，参究槌拂捐。","东归住双峨，户屦来后先。","光风流转处，名满越与燕。","哲也继欣出，研坳侵雪肩。","芳丛依苔石，瘦竹穿涧泉。","神闲妙盘礴，思入孤桐弦。","朝阳鸣孤凤，秋空唳饥鸢。","想从闻思脩，六根互相宣。","听者悉说喜，赠章动盈篇。","恨非昌黎伯，乃欲观其颠。","要须三摩地，契悟非言传。"]},{"t":"马氏云山祖茔图","f":"五言古诗","c":["孔子少也孤，不知防墓地。","亲殡五父衢，问之邻母氏。","嗟我云山翁，追远心不置。","祖茔在阳冈，距今已七世。","松楸写新图，名笔为题识。","国史既特书，铁史光相继。","眷兹河阳山，白云浩无际。"]},{"t":"山居图二首 其一","f":"五言律诗","c":["卑栖拙谋身，旷望时纵目。","山气晓亦佳，烧痕晴自绿。","轹金扳松屑，解缨濯岩瀑。","幽怀良自怡，谁云有延促？"]},{"t":"山居图二首 其二","f":"五言律诗","c":["惟是安僻境，本非薄荣名。","松根听泉坐，溪边看云行。","夜雨下黄叶，春风开紫荆。","物理有代谢，古人谁独生？"]},{"t":"凌波仙","f":"五言律诗","c":["迢迢湘浦秋，盈盈洛川月。","镜空离鸾舞，天远孤鸿灭。","木叶向人下，瑶草带愁折。","有怀无由寄，琴心谩三叠。"]},{"t":"岁晚寄郦尚德、马民立","f":"五言古诗","c":["玄冬夜何长，白日寒苦短。","流光迈鲁疾，浮态怯齐缓。","画沙劳纤锥，窥天费幽管。","事靡有定形，犬氂马生卵。","岂无酒消忧？","累觞弗能满。","冒雪梅含英，香露珠纂纂。","西窗期同观，赓咏倾茗盌。"]},{"t":"竹夫人","f":"五言古诗","c":["墨台有淑媛，不嫁敛眉妩。","江南夏六月，火五金伏土。","于时媛以洁，空中不受暑。","携持枕簟间，断非戕斤斧。","况复不妒忌，凉薄善自处。","纱厨奉清欢，通宵默无语。","君子加保抱，安寝梦净侣。","各弹绿筠操，就中节更苦。","严冷莫可犯，编排其有序。","玲珑瑑黄玉，珫通映朱户。","舞榭洞八窗，歌台高百堵。","弗贻六宫怜，顿消汗如雨。","安知凉秋至？","君颜不复睹。","此时愁绪多，恰同齐纨素。","用舍良有时，宁问今与古？"]},{"t":"姑苏台","f":"七言古诗","c":["城西高台高百尺，传是吴王旧游迹。","百花正开西子醉，明月芳洲照清夕。","娇颜如花醉王侧，城上乌啼晓星白。","歌鼓声消醉未消，越王已将兵来朝。","鏦金挝鼓殷天地，兵败可复栖夫椒？","吴人遗恨化潮汐，暮往朝来箭径直。","不然自可君甬东，何用萧萧马嘶驿。"]},{"t":"夏驾湖","f":"七言古诗","c":["吴王城西夏驾湖，至今草木青扶疏。","想见吴王来避暑，后宫濯濯千芙蕖。","酣红矗翠总殊绝，谁似西施天下无？","西施醉凭水窗睡，曼衍鱼龙张水戏。","月上湖头王醉醒，归舟莲炬繁如星。","不知拥扇暍人者，日夜窥吴不暂舍。"]},{"t":"吴桓王墓","f":"七言古诗","c":["有吴桓王之墓田，乃在盘门南郭边。","墓中玉凫久化土，石上赤乌犹纪年。","寒食无人洒麦饭，东风满地飘榆钱。","功昭前代启吴祚，葬地合择名山川。","阖闾城南不百步，土薄易致耕夫穿。","昭纮众臣号详密，虑不及此宁非愆？","缅思山东举义日，郿炷顾已无诸贤。","惟王父子起相继，黄星闪避东南天。","假之修龄定四海，许下岂容瞒著鞭？","凿山掩匠等发掘，朽壤一抔谁独专？","白杨萧萧北邙路，姓名能得几人传？"]},{"t":"岳武穆王墓","f":"七言古诗","c":["栖霞岭南湖水阴，墓木两株高百寻。","鬼神撝护霜雪干，日夜怒号风雨音。","山僧纸钱每自挂，陇酋金槌那得侵？","精忠既已塞天地，英爽尚尔盘山林。","恨虽无血可化碧，世故有人能范金。","恭惟父子一抔土，尚想君臣千载心。","万松岭前行殿废，五国城头寒漏沉。","空令遗黎痛至骨，荒坟一上一哀吟。"]},{"t":"古墙行，并序","f":"七言古诗","c":["崒嵂环墙连数堵，宋亡犹是循王府。","渡南功臣王第一，赐第钱塘贮歌舞。","筑墙远取南山土，军士肩赪汗流股。","桢干停匀杵筑坚，小却犹支三百年。","当时能留岳忠武，返旆定可铭燕然。","嫖姚忘家子婿戮，宰嚭卖国身名全。","偷安湖山忘大辱，诏谕江南等臣仆。","萧墙缭周千柱宫，只欠甑泥蒸后筑。","带砺镌铭在甲第，筑墙不厌高于屋。","远雁秋横五国城，帛书无复泪交倾。","可怜忠臣痛刻骨，空令志士死结缨。","佞显忠诛谁得失？","二百年馀昭白日。","旧时每见古墙边，鬼灯夜暗光如漆。","墙土于今化作灰，欲问故老心先摧。","只有省垣新筑后，鼓角声殷吴山隈。"]},{"t":"吊刘龙洲墓","f":"七言古诗","c":["宋渡南如晋永嘉，屈辱更甚惭栖鸦。","才贤尽毙贼桧手，君相甘同鲁妇髽。","孝皇悲愤痛莫雪，士逃窜诛能几家？","翁也诸侯老宾客，有泪每落西风笳。","南楼载酒桂花晚，经纶志在言非誇。","且将南山抉虎穴，岂但东海刳鲸牙？","长敌疏章过恸哭，况闻远雁来龙沙。","林苏与白出处异，便欲呼起能无哗？","醉乡生死忘今古，酒熟莼香鱼可叉。","和戎自有祈请便，经天非无博望槎。","瞪视乾坤谢轩冕，朽骨深瘗山之涯。","娄江东流山蕴玉，翁也墓此谁疵瑕？","荒陵无人浇麦饭，废家有树开梨花。","荧荧鬼燐出松坞，想翁来游路匪赊。"]},{"t":"重建岳王精忠庙，谢李全初长司","f":"七言古诗","c":["忆昔绍兴南渡时，从王百万虎与貔。","鄂王奋身起偏裨，能以百战扶国危。","师行动以纪律持，屯行野次人罕知。","堂堂大将精忠旗，敌人不敢正眼窥。","连城之壁无瑕疵，如何青蝇玷污之？","后来礼葬西湖湄，血已化碧无完尸。","于今宋亡宗社隳，独遗墓木蟠孙枝。","夜啼鸺鹠啸狐狸，过而问者知谓谁？","庐陵李君每涕洟，乃坐幕府深自惟。","不独罄发囊中资，又属州人使共治。","徘徊经营出成规，庙遂落成焕桷枅。","烝尝复享崇令仪，父老瞻拜咸嗟咨。","赞君为政能及兹，只今解任舟将移。","何以表君去后思？","爰勒坚珉著贞词。","昭示亿年匪誇毗，过者下读丽牲碑。"]},{"t":"长孙皇后免冠图","f":"七言古诗","c":["贞观圣人还紫宫，按剑欲杀田舍翁。","翁本帝仇今作辅，逆鳞易批难论功。","后闻君言心惨恻，自古君明则臣直。","直臣脱若死无辜，贱妾一身亦奚惜？","免冠再拜明主前，阴扶红日行青天。","他时拭目看陵树，不以大义亏其全。"]},{"t":"渊明归庄图","f":"七言古诗","c":["终风昼霾八表昏，有眼不睹东方暾。","只应门前种杨柳，山河已改枝柯存。","原田畇畇水漾漾，归来有酒盈清尊。","醉乡生死岂不好？","悬书甲子明深恩。","仁人义士久黄土，丹青彷佛柴桑村。","画图不尽古今意，寒蛩夜语秋槐根。"]},{"t":"东坡赤壁图","f":"七言古诗","c":["奎星堕地不化石，化作盘天老胸臆。","清禁森严著不得，半夜吹箫过赤壁。","百亿鱼龙不敢听，万古东流月华白。"]},{"t":"温日观画葡萄二首 其一","f":"七言古诗","c":["伊昔钱唐温日观，醉兀竹舆殊傲岸。","却将书法画葡萄，张颠草圣何零乱。","枝枝叶叶点画间，醉瞠白眼看青天。","狂呼大盗杨总统，天不汝诛吾厚颜。","杨加箠死曾不畏，故老言之泪尚潸。","画成葡萄谁赏识？","惟有鲜于恒啧啧。","醉叩斋室支离疏，拊摩悲歌泪填臆。","鲜于设浴师浣之，为师涤垢曾弗辞。","人言结袜张廷尉，千载风流宁异兹？","蔓如龙须实马乳，问师挥毫奚独取？","只因汉使远持来，野老诗成泪如雨。"]},{"t":"温日观画葡萄二首 其二","f":"七言古诗","c":["故宋狂僧温日观，醉凭竹舆称是汉。","以头濡墨写葡萄，叶叶枝枝自零乱。","陇酋时有连真珈，每欲邀师饮其家。","路逢其人辄大骂，欲泄愤怒宁辞挝？","鲜于爱师工字画，北面从师学波磔。","写出葡萄皆法书，二王楷范从师得。","困学斋前支离疏，师来或哭或歌呼。","醒涂醉抹不可测，其言皆足警懦夫。","先生弊庐耿家步，阿师旧日经行路。","月落山空唤不应，尚想秋棚漙白露。"]},{"t":"赠无锡强教谕","f":"七言古诗","c":["义门影逼梁溪水，诵声琅琅长应耳。","中有文儒名父子，教铎铿鍧相继起。","毗陵去家不百里，蔼蔼春云尽桑梓。","三年职教识才美，鼓箧来游无远迩。","振衣升堂静兀兀，槩于群经味其旨。","坐见金精出炉箠，泮池冰消跃赤鲤。","坛杏缄春红蕊蕊，政成南归黠行李。","明月清风满船尾，归娱慈亲綵衣喜。","醲酒华堂纷拜跽，棣萼春辉交韡韡，咸祝先生此升矣。"]},{"t":"送范子方掌教","f":"七言古诗","c":["江南乔木几家存？","魏公犹多贤子孙。","根株久浸诗书泽，萌蘖长承雨露恩。","美化山长尤秀出，翩其令仪如玉温。","观光帝都富述作，传经亲闱加讨论。","一官不厌客毡冷，暂尔定省违朝昏。","侧身霄汉度林岭，照眼井络逢人村。","东风吹衣昼袭袭，北斗横屋夜暾暾。","公侯复始自今日，浩荡恩波白兽尊。","传闻吾家光禄坟，青松上啼古帝魂。","大眦十围阅世久，禅旁徂杙无留根。","贞元丞相久寂寞，不辞为庶为清门。","得从君去拜桑梓，胜倚孤云溅泪痕。"]},{"t":"赠达长司懋衡","f":"七言古诗","c":["十月二日君生辰，菊有黄花霜露新。","汉朝既须召贾马，嵩岳岂徒生甫申？","众瞻云霄黄鹄举，自爱江海白鸥驯。","乌丝昼临峄山刻，银笺夜制吴宫春。","政尔扬舲海潮上，忽然煮茶溪水滨。","啭枝幽禽语留客，搀腊野梅开向人。","苍生却问谢安石，白首可同郑子真？"]},{"t":"送顾县尉定之","f":"七言古诗","c":["虎头诸孙岂诚痴？","飞墨即是苍筠枝。","故家乔木尽黄落，此君贞节仍坚持。","向年毗陵为录判，正声早腾青玉案。","亲殁天南柩返吴，弃官急归方寸乱。","从兄负土成孤坟，天平山麓黯秋云。","哀哀泪滴坟上土，终制北谒天皇君。","一官又赴同安尉，白云黄叶秋无际。","道经武夷山下路，遏云棹歌迎鼓枻。","山中徵君峨小冠，能令幽居帝画看？"]},{"t":"赠藏书顾明则","f":"七言古诗","c":["昔人于书皆手钞，六经子史方神交。","编摹虽勤不闻道，是亦蠹蟫书作巢。","积书之家费装缉，褙工亦由书传出。","一朝妙手完缺残，正如云开睹初日。","我欲一问顾生家，松陵春晴桃始华。","蟠胸万卷老多忘，检卷只如昏树鸦。","嗟嗟书生吴钜族，风霜日夜摧乔木。","虽然业身簿秩间，有眼且看江南山。"]},{"t":"古书行，赠吴孟思","f":"七言古诗","c":["苍颉四目通神明，制字以来几变更。","籀创大篆岂柱史？","石鼓有刻非无徵。","骊珠煌煌几千颗，照烛万世开章程。","周平东迁帝纽解，甄酆继出加研精。","秦斯学荀儒运阨，独负小篆超焚坑。","戈森剑列出华玉，百世是宝堪依凭。","次仲忽挟八分起，喜动吕政消威棱。","一朝槛车化鹤去，传闻无乃非人情？","政方鞭戮海宇日，程邈继仲尤知名。","六国灭姬旋自灭，人如乱麻死长城。","神工异画先后出，隶法变篆由邈兴。","十年覃思非不苦，习趋简便令人轻。","堂堂逵门许叔重，愤悱缺讹复著经。","三才万物总蒐讨，一掣屋蔀瞻繁星。","慎于六义功不细，朽骨逮今馀德馨。","汉章变草本伯度，波磔与隶犹相仍。","俗书姿媚相扇告，韩论匪激毋深惊。","千年阳冰绍斯迹，有茂其实蜚英声。","圭璧煌煌照衰世，白马记与庶子铭。","两徐识解更卓特，著书翼慎言庚庚。","张侯豹姿编复古，金薤琳琅垂九清。","皇元笃生赵文敏，扫世糠秕开群盲。","龙翔凤翥彩云晚，夹以日驭扬双旌。","自公骑箕上天去，众论悉与濮阳生。","生名吴睿孟思字，篆隶可宝如璜珩。","周旋向背尽规矩，分布上下纷纵横。","囊锥画沙泯芒角，宝树出网含光晶。","研裂云根剑就淬，射穿杨叶弓开枰。","刊题班班满山石，姓名往往闻帝京。","赠言无如胡汲仲，我乃蚓窍蝇薨薨。","阖闾城中每相见，愧我头白君眼青。","长歌哦成三月暮，妒妇无能空拊膺。"]},{"t":"龙香行，赠吴国良","f":"七言古诗","c":["张公洞中芝草春，帝藏宝书更几尘？","中有龙香烧墨法，古苔溜雨松肤皴。","木公窃窥试造后，至今法行溪水滨。","吴生妙解不求似，独造万古工何纯！","玄霜夜捣玉兔臼，黑琼晓剥苍蛟鳞。","制成比之犀截角，研罢顿似鸾凭茵。","姿如青铜色如漆，并潘便见亦相亲。","老奚父子委世久，潘李竟谁追后尘？","嗟生一朝遇赏识，会同南琛贡紫宸。","愿宝龙香古圭璧，明月清光长照人。"]},{"t":"相地余君祥赠言卷","f":"七言古诗","c":["我早不识余山人，湖海名知三十春。","闻其欲识天下士，不厌四方走踆踆。","朅来中吴春苦雨，雨窗峭寒肌骨皴。","袖有赠言成大轴，读未卷终伤我神。","儒先沦落日已尽，我独未死如枯鳞。","涸辙曾无斗升水，破靴厌踏康庄尘。","生言宿知地理学，转移造化抽机轮。","黄箸定钤司马氏，青囊为书郭景纯。","二子骑箕上天去，遗编凭谁据其津？","余生两眼炯秋月，遍观山崖与海滨。","先辈而今木已拱，后生蹇予蠖不伸。","何处青山可埋我？","免使乌鸢蝼蚁嗔。"]},{"t":"舒大尹伯洪之任晋陵","f":"七言古诗","c":["西门晓送舒晋陵，十里冲冲闻凿冰。","邑侯生长单父邑，弹琴化行咸服膺。","民风莫讶北南异，身教始为今者称。","我歌侯听意良苦，且住槽拨朱丝绳。","田间困悴非一日，锥刀割剥动千层。","孱民不殊罝里兔，猾吏却如霜后鹰。","豪强结托相表里，机变聚集誇才能。","茧丝何曾宿杼轴？","粟穗况欲栖沟塍。","煌煌列宿在霄汉，扣首昊天呼不应。","风声俗习一至此，问侯何以宽凌兢？","侯从胄监学古训，仁义楼橹身先登。","雄谈浪浪泻河汉，伟度浩浩吞鹍鹏。","力行以言拯颓俗，定奋其力支崩腾。","坐令凋瘵复完实，岂但贤劳不次升？","腐儒歌长侯勉听，无肉如陵酒如渑。","歌长意苦白日暮，忽见新月上渔罾。"]},{"t":"送韩从事玉温之闽","f":"七言古诗","c":["韩侯魏公之子孙，传家故笏今犹存。","吏程于今重漕府，人望自昔推名门。","风帆晓趠凤洲过，铁碇夜划鲸波浑。","七闽宏开元帅府，二品欲均丞相尊。","檐团煌煌荔子叶，庭走阴阴榕树根。","迁升郎署不惮远，遄拜朝命兹承恩。","道山亭上登临日，为赋海涌玻瓈盆。"]},{"t":"送汪秀才瑩中","f":"七言古诗","c":["三十年前湖上路，君之外舅钱塘簿。","春风双鬓绿于云，岂料于今各迟暮？","迟暮相逢两相顾，出者非迂处非误。","君出才如班定远，我处心惭黄叔度。","向年边氓弄锄梃，屈君从戎曾不腐。","皇家福力九鼎固，尔民何异罝中兔？","上功幕府寂不闻，一命低徊乐其素。","参佐南安郡幕归，行李萧然只如故。","于今复理吏部铨，束书朝上阊门船。","柳条缄黄雪初霁，鸥波吹白舟当牵。","翻书蓬窗遮老眼，沽酒野店浇残年。","想见新春花欲然，君应醉倒春风前。","青云故人布百辟，黄纸除书来九天。","得官南归应过我，姑苏台东野水边。","却问朝端泰秘监，何时寄我归来篇？"]},{"t":"赵松雪画","f":"七言古诗","c":["鸥波亭前千叠山，缥缈峰峦烟霭间。","既如春云多态度，复似静女工幽娴。","老槎霜寒露刻削，崩湍雨霁声潺湲。","飞楼涌殿出林表，中有逸人相往还。","风帆截溪马载道，兼有艇子维沧湾。","有时扣舷一清唱，有时谈玄一破颜。","吴兴仙翁补天手，毫端五色春斓斑。","画成未数董北苑，王维二李相跻攀。","自翁骑鲸上天后，至今玉佩声珊珊。","空令下土宝遗墨，真赝纷纷谁与删？"]},{"t":"赵仲穆画","f":"七言古诗","c":["王孙画思凌紫青，千峰削出秋冥冥。","丹台疑通玉京路，飞瀑上溅银河星。","抱琴随马风泠泠，定知不是王门伶。","山空水流木叶落，曲终正不求人听。","溪流明灭夕阳晚，似有樵唱来岩坰。","王孙归卧鸥波亭，钧天清都梦始醒。","浮云变灭不挂眼，盘石溪边且濯缨。"]},{"t":"李龙眠唐马，仲穆临","f":"七言古诗","c":["龙眠画马妙入神，貌得唐时马与人。","人通马语默相契，马知人意更相亲。","文皇昔御六龙出，天为圣主产骐驎。","开元马牧蕃盛日，泛驾齧膝谁能驯？","自昔龙驹有天骨，骕骦独起秋轮囷。","西巡不复觞王母，东归政尔惭直臣。","马图流传至汴宋，玉骢紫燕聊前陈。","守文之君保成业，不肯一日开边尘。","遂寘骅骝鼓车下，猛蛟失水无完鳞。","柏台退休亲貌得，画意逮逼曹韩真。","画史才知粉墨趣，学士乃通元化因。","曹韩骨朽伯时死，馀不溪上苕花春。","临摹不得画史意，掩卷愁眉谁与伸？"]},{"t":"徐孟达别墅冬日海棠","f":"七言古诗","c":["猗唐厚德徐有功，力回凶残致时雍。","子孙蒙休百世下，草木作花严冷中。","园林尚或保剩绿，霜霰不敢欺嫣红。","金盘朝露洗睡态，锦丝步障围春容。","流年固如东逝水，衔子岂必西飞鸿？","何异佳人倚脩竹，尚矜绝艳弹孤桐。","徘徊树下三叹息，人生迟莫将无同。"]},{"t":"王元章白描梅","f":"七言古诗","c":["王郎笔底无纤尘，只有万斛江南春。","疏花冷蕊禁不得，珠明玉润前森陈。","珊瑚交柯撑铁网，金铓铄日张龙鳞。","咸平处士西湖滨，风雪满头肌肉皴。","长歌短吟梅树下，声诗写得梅花真。","王郎晚载剡溪雪，舣舟孤山一问津。","色香声尘尽夺取，高挥大抹骇世人。","旧时娟娟里湖月，清光长照无疏亲。"]},{"t":"顾定之墨竹","f":"七言古诗","c":["虎头诸孙妙飞墨，丛篁脩纤傍湖石。","只疑湘江水湛碧，英娥骑鲸去不返，千古遥岑绾秋色。"]},{"t":"黄子久山水二首 其一","f":"七言古诗","c":["小黠大痴谁复然，画山画水亦随缘。","悬崖绝谷喷流泉，此中即是安养地，九品莲华光烛天。"]},{"t":"黄子久山水二首 其二","f":"七言古诗","c":["众人皆黠我独痴，头蓬面皱丝鬓垂。","勇投南山刺白额，饥缘东岭采青芝。","仲雍山趾归休日，尚馀平生五色笔。","画山画水画楼台，万态春云研坳出。","只今年已八十馀，无复再投光范书。","留得读书眼如月，万古清光满太虚。"]},{"t":"向年与岳汉阳、赵宛丘同登荆溪王氏仁寿堂，今几四十稔。时允同尚未生，兹允同出拜，感念今昔，赋以与之","f":"七言古诗","c":["昔年尝登仁寿堂，岳赵两侯与颉颃。","周情孔思蔼胸臆，商彝雒鼎陈宝藏。","名画珠官启丹碧，法书金薤垂琳琅。","官窑器列八珍馔，博山炉焚三杰香。","稽经考史发言论，跨秦越汉谭文章。","惟时石坞梅花吐，肩舆起穿林岭长。","溪回路转雪欲作，薄暮似绕罗浮傍。","归途列炬兼击柝，候人奔迓遥相望。","南枝禽翻北枝冻，置酒张灯罗艳妆。","主宾一时极驩会，转头于今四十霜。","赵登廊庙岳物故，我仍饥驱行四方。","人生那能免离合？","世运乃尔罹惨伤。","乾坤疮痍战尘黑，溪山破碎愁云黄。","华屋终焉变瓦砾，旧厌梁肉今糟糠。","子之家居尤可念，蒿艾丛深蹲虎狼。","幸哉仁者必有后，出赘于此存豪芒。","子之拜我我增慨，衰颓有几桑榆光。","朋俦凋落世变苦，安得不及我涕滂？"]},{"t":"送俞教授之馀杭","f":"七言律诗","c":["馀杭县前春水生，校官书舟如叶轻。","莺啼讲坛杏垂实，鱼跃泮水芹抽茎。","易于观天圣域敞，文者载道天机精。","明年彤庭对策后，我亦阊门迓前旌。"]},{"t":"送俞叔元从游慈溪陈文昭","f":"七言古诗","c":["百舍重趼从师游，为道不为利禄谋。","今子远鼓浙东枻，涛江日暮青山稠。","慈溪为县山水幽，制锦者谁陈太丘。","退食何曾废探讨，固应户屦远相求。","它时卒业归语我，坐见一鹗横清秋。"]},{"t":"送李运使海漕抵京，见宣城贡侍制","f":"七言古诗","c":["易于涉险必曰川，何况航海决九渊？","海虽无风浪或颠，银山雪屋相崩骞。","国家鸿庥上际天，漕海运粮今几年？","波神水妃相后先，分护粮艘咸周全。","棹郎捩舵歌扣舷，南风趠帆到幽燕。","万井白袅朝炊烟，青驹之年福更延。","上帝降监加矜怜，天子明圣宰相贤。","明烛万里无私偏，春运已达北海壖。","天吴帖首海若眠，李郎夏运能勉旃。","海波镜平粮在船，由郎心纯志确坚。","敬亭之山秀而妍，幼从贡公读陈编。","志存功业永久传，悬知此行尤静便。","定膺上赏坐玳筵，金缣缥醪宠命宣。","应从贡公见榻前，清光咫尺如霏烟。","贡公若问老郑虔，为言白头仍草玄。","海宇清晏无戈鋋，咏歌太平老林泉，却寄贡公山木篇。"]},{"t":"寄云南萧总戎","f":"七言古诗","c":["将军昔麾白虎幡，指率虎士平云南。","大山丰林犀象窟，青山一束西横担。","诸军落险坐如猬，下嗔长鲸手独探。","威行武侯擒纵地，大旗森立如松杉。","整师徐行身后殿，点胄还国无留簪。","总戎既已等却谷，相国正可同曹参。","自参大政论国柄，载具清静民心甘。","凤驾祥云忽铩翮，公论在人宁久酣？","皇明鼌彻烛群连，蔀蔽尽彻俭谋戡。","将军复整苍玉佩，入朝拜手仪容谙。","念臣已老心则壮，宝镜在匣秋儋儋。","圣君万岁国基固，明堂缔搆须楩楠。"]},{"t":"送刘朝章同知赴任","f":"七言古诗","c":["尚书向任杭推官，宛丘赵公最交欢。","子时方年二十许，身衣大布头南冠。","二公相予忘齿爵，稽经抽史言盘盘。","赵公骑箕尊府老，会合无由空嘅叹。","尊翁后贰吴府政，吏畏民思闾井安。","只今星霜十五易，北归悬车魏地宽。","郎君翩翩蒙世泽，气貌润哲神仍端。","同知黄岩行有日，部从南向千峰峦。","徵诗于予感衰老，况复秋深霜露寒。","客怀萧萧诗鬓白，江浦凄凄枫叶丹。","自惭居贫无赆饯，鸿飞万里须脩翰。","高天无云卿月皎，候吏侧足迎征鞍。","民思善治甚饥渴，报政何以苏凋残？","尊公在此徯佳信，声腾实著无留难。"]},{"t":"题张伯雨留别卷","f":"七言古诗","c":["句曲外史儒仙师，开口论事剑差差。","诗律精严夺天巧，字画峭重含春姿。","一朝飘然上京邑，赤墀不拜惟长揖。","名称藉藉诸公间，落纸云烟粲星日。","玺书令任西湖滨，忽思骑虎朝玉宸。","大茅峰头斟北斗，剑佩色映江南春。","山经幽文与道帙，归藏灵涧之石室。","小劫犹割紫琳腴，大书应按皇人笔。","鬼物守护今几年？","阖户勒铭师亦仙。","酒星在天照酒泉，师醉而死方陶然。","如何卧病二十日？","鹤骨瘦筋神隼急。","一朝返真大浣洞，西湖山空鬼夜泣。","飞墨如雾留人间，读之锵然鸣佩环。","疑师不死不得见，老泪洒入秋苔斑。"]},{"t":"惟则天如师子林","f":"七言古诗","c":["万竹阴阴师子林，苍霏如雪不厌深。","影当初阳鸾凤舞，响作平地蛟龙吟。","契机元非击后悟，乘凉已在栽时寻。","行鞭土酥虽诘屈，沛润法雨尤阴森。","笋时不传餐玉法，定起每听贯珠音。","那知阎浮有六月？","只缘毗耶无二心。","眼光固已烁天地，王度政尔式玉金。","老矣蒲鞋尚堪织，贫岂藜羹长乏斟？","养威窟中善自爱，解铃颔下知谁任？","扰扰尘劳竟何以？","便应于此投华簪。"]},{"t":"送诗僧珩书记","f":"七言古诗","c":["吴僧娟娟珩上人，诗如岳面青嶙峋。","旁支小山各秀出，吞云泄雨干星辰。","陈高复来说珩好，思若美玉蒸孚尹。","我老于诗苦思短，援笔欲下仍嚬呻。","奏香拟绕玉皇案，放棹却入桃源春。","艰难若此良自笑，束烧不爇釜底尘。","如何诸君擅天巧？","珩也又复能清新？","百年几见光岳合，四海此喜文章纯。","吾闻桑门重行解，言必与道无碯磷。","西风摇落雁南乡，长歌送子空沾巾。"]},{"t":"送颜陋隐道士","f":"七言古诗","c":["颜阖鍊术三茆山，术烟如云紫翠间。","久御师坛黑虎出，又骑仙岩白鹤还。","符箓登真有要诀，祠灶却老须玄关。","宝书仍傅具茨牧，珠实政缀玄都班。","是中有人炼玉质，不逐颓景凋朱颜。","脩辞如兰吐酷烈，濯足古涧听潺湲。","企余东望不可即，天风泠然锵佩环。"]},{"t":"送聪首座游升","f":"七言古诗","c":["昔年龙河帝作宫，万础搆出金芙蓉。","祝釐至命黑衣相，董役乃是乌台公。","帝乘云去师示寂，瓦砾依然化金碧。","搥钟吹螺震天地，游从每振东南锡。","聪也金鳌背上人，金翅擘海驱波神。","典座南屏万峰上，高阁瞪睨青嶙峋。","来吴欲作凤台去，词锋欲写秦淮树。","业材参天必豫章，匠石何尝后梁柱？","渺渺长江无尽流，诗成为寄波间鸥。","自昔六朝帝王州，老夫每欲东南游。","白下江山暮云合，乌衣巷陌斜阳愁。","古人销亡景物在，著我一赋商声讴。"]},{"t":"赠日本僧","f":"七言古诗","c":["海以岛屿为连城，其大每与龙伯争。","珊瑚柱冷建宫阙，翡翠浪暖开蓬瀛。","亦有神僧出其国，能与古佛同无生。","饭香盛贮帝青钵，身垢沐浴琉璃瓶。","锡飞曾追独鹤远，杯渡至比群鸥轻。","辅教编成献明主，弯弓机险开群盲。","梅花飞雪岁云暮，冰树削玉天初晴。","鱼翻春波迓鼓柁，马嘶晚驿知扬旌。","荡茶榻前启沃处，不让义夫留大名。"]},{"t":"题夷僧写兰卷","f":"七言古诗","c":["老禅昔从日本来，足踏万里鲸波开。","金仙所居太霞上，五色芝草为楼台。","国香中有兰与蕙，成丛托根在蓬莱。","老禅一见契幽独，叶叶茎茎在心目。","砚坳盛得楚芳魂，九畹春风种华玉。","紫鳌背开龙伯宫，千柱结搆神施工。","妙高台上醉挥墨，光云闪映珊瑚红。","贤王分茅甸南服，万马屯云夜如簇。","独延老师至王宫，霜毵毫蘸松煤绿。","为书蛟龙古奇字，喷雾拿云看不足。","老禅担簦东入吴，白虹夜腾西太湖。","飞墨何分醉和醒？","高天顷刻青模糊。","横挥直抹恣图写，太虚空里无精粗。","诸方非无大床坐，合让主席候挥鈇。","只缘自有宝玉刹，千层楼阁金银铺。","人间腥腐蜗一壳，蠛蠓聚散真斯须。","定追他日议天统，大沛法雨滋焦枯。"]},{"t":"钟馗部鬼图","f":"七言古诗","c":["老髯足恐迷阳棘，鬼肩藤舆振双膝。","前驱肥身儿短黑，非髯娇儿则已腊。","后从众丑服厮役，担携鬼脯作髯食。","鬼肌未必能肥腯，餔之空劳髯手擘。","彼瘦而巾褙长窄，无乃癯儒执髯役。","其馀丑状千百态，专为世人尸辟怪。","楚龚狞老非其类，请问何由识其槩？","想龚目睛烁阴界，行尸走鬼非殊派。","民膏民脂饱死后，却供髯餐缩而瘦。","无由起龚问其候，有啸于梁妖莫售。","大明当天百禄辏，物不疵疠民长寿。"]},{"t":"馗妹图","f":"七言古诗","c":["天宝治衰妹兄出，白昼宫庭馘狞獝。","妹时何在不佐兄？","靓妆自衒妖娴质。","后来形见知何所？","百鬼尊之莫敢睹。","提剑跃马从其兄，每为人家守环堵。","老韩饥穷夜缚船，送之不去今几年？","妹肯从兄肆屏逐，我亦家富黄金钱。"]},{"t":"谢自然像","f":"七言古诗","c":["老韩语屈雄世间，好用险语搜神奸。","上仙飞空诣丹阙，政自与世无相关。","奚为造言极诬诋？","何妨月照千江水。","龙伯珠宫深处明，鹤发嵩师酝时喜。","扶植世教须老韩，天风不碍锵鸣鸾。","不见果州南充县，香火至今盟未寒。"]},{"t":"春华蛱蝶谣，题舜举画","f":"七言古诗","c":["华魂迷春招不归，梦随蝴蝶江南飞。","碧蕤粉香酣不起，卧帖芳茵唾铅水。","痴娥眼娇错惊顾，解裙戏扑沾零露。","折钗搔首笑相语，阿谁芳心同栩栩？","颓云流光空影寒，冰弦缄恨啼阑干。"]},{"t":"赠笔工沈日新","f":"七言古诗","c":["南州先生真玉人，苏家季孟世绝伦。","良公骑尾上天去，清润馀流溪水滨。","东老之家酒熟未？","其孙犹以縳笔闻。","公家兄弟不负笔，我辈颓之天且嗔。","不如醉用榴皮写，仙人岂亦能书者？"]},{"t":"赵千里聚扇上写山，次伯雨韵","f":"七言律诗","c":["宋诸王孙妙盘礴，万里江山归一握。","卷藏袖中舒在我，清风徐来縠衣薄。","文采于今沦落馀，雕阑玉砌凄烟芜。","宝玉不随黄土化，门上空啼头白乌。"]},{"t":"赵善长枉顾玉山，遂以绢为予索画，并诗其上","f":"七言古诗","c":["顾家绢如鸡子皮，赵生画似鲛人机。","冰丝瑩滑始受彩，天藻绚烂方含辉。","海波金芒鳌背上，溪树翠锁春洲肥。","渔师出港晴举网，野老问渡寒褰衣。","试讯何从有此景？","顾在笔底纵横挥。"]},{"t":"崇碧轩","f":"七言古诗","c":["江城乔木春阴薄，故家文献多沦落。","雨声环堵长蓬蒿，鬓影衰年饭藜藿。","见说张家崇碧轩，楩楠豫章青拂天。","后皇嘉树无不有，雨露所濡皆可怜。","何时从子松根下？","读书逍遥以忘年。"]},{"t":"渔庄","f":"七言古诗","c":["濠上春晴花朵朵，施周强知鱼与我。","争如顾循读书倦？","馺沓浪花宵鼓柁。","船头列炬船尾唱，绳擉如云翻水上。","并刀斫雪鲙缕飞，拍拍茆柴荐新酿。","庄上东风柳欲绵，鲤鱼吹浪迎归船。","由来名教有乐地，看书却扫消残年。"]},{"t":"梅隐","f":"七言古诗","c":["昔者先人住杭州，和靖祠前水东流。","弊庐与祠政相近，看梅吊古山之幽。","咸平梅花三百树，无复春风一树留。","荒烟野花开踯躅，落日林树啼鸺鹠。","黄昏娟娟里湖月，每为香影含孤愁。","长怀此花冰玉质，无言自足令人羞。","眼明波间双白鸥，亦复与世相沈浮。","不见梅花已悽怨，况闻笛声湖水头。","青山难消楚人恨，白发易感商声讴。","吾庐亦岂能自爱？","种梅绕屋休嫌稠。","三十年间屡易主，归魂每梦花间游。","因观此图重叹息，万事何异水中沤？","知君断非充隐者，卜居梅花善自谋。","我亦漂零江海上，悠悠千古一登楼。"]},{"t":"玉山佳处，为顾仲瑛赋","f":"七言古诗","c":["东望东吴积水深，海天削出青瑶岑。","肃侯诸孙有基搆，界泾筑室如山林。","石根孚尹蒸玉气，岸曲窈窕来跫音。","笼鹤教驯合舞节，池鱼出游听鼓琴。","楼台花雨众香国，书画芸香千古心。","按歌宁辞夜投辖？","弹冠又须朝盍簪。","已傍苔矶学钓擉，更上风磴穷登临。","竹梧参天凤鸾集，老夫为尔长歌吟。"]},{"t":"湖光山色楼","f":"七言古诗","c":["顾家湖光山色楼，登览近在西檐头。","朝烟帖水白初散，晴云出坞青相缪。","浪花铄闪上初日，崖气澄横如凛秋。","宿草依依仲雍墓，孤帆摇摇范蠡舟。","灵来每见云旗下，物换几番汀草抽？","何人孤啸答渔唱？","有客五月披羊裘。","主人领客遥指点，童子昔时曾钓游。","曳裾王门尘眯目，担簦客乡雪满头。","何如长年老于此？","登临笑乐孰与俦？","玉关西望不得入，辛苦才封定远侯。"]},{"t":"云山高隐图","f":"七言古诗","c":["大山巀嶪如张旗，小山偃蹇如牵衣。","岩头千仞泻飞瀑，迸珠溅雪交横飞。","林庐隐隐空中起，青红栋宇相轩委。","中有幽人歌紫芝，自采药苗临涧洗。","乔林露下青童童，交柯老干森虬龙。","岂无明堂栋梁柱？","还当采献明光宫。","宁无谷底白驹客？","考槃歌中风落日。","画图难写西隐踪，一曲鸾笙度空碧。"]},{"t":"虞胜伯江山风雨图","f":"七言律诗","c":["雍公之孙胜伯父，落笔惊人意独苦。","篆籀从衡写风雨，平林远岸舟横浦。","想从出蜀看山多，笔锋森然如斮戈。","春秋著成可奈何，酒酣拔剑须君歌。"]},{"t":"郑禧之古木图","f":"七言古诗","c":["吾宗有子擅风流，履行只如陈太丘。","复向仇池写林薄，六月阴森如凛秋。","前脩凋零吾亦老，落日孤云生晚愁。"]},{"t":"钩勒竹","f":"七言律诗","c":["凤凰仇池五色毛，晔晅一如金错刀。","欲斮沧海上初日，下有积石定风涛。","曾向人间拾凤毛，从衡文采自挥毫。","龙孙啸咏求摹写，露洗珊瑚月影高。"]},{"t":"题梅，为人寿","f":"七言律诗","c":["二月十日君生朝，连日重雾今日消。","梅花含春照池水，眼明见此千琼瑶。","我愿君年等金石，梅花结子调鼎食。","年年为君持寿杯，大醉花前华月白。"]},{"t":"天台山图","f":"七言古诗","c":["万八千丈天台山，仙人抱琴时往还。","丝声落涧秋潺潺，曲终蜚云舞玄鹤，霞光楼观难跻攀。"]},{"t":"芭蕉庵，为僧赋","f":"七言古诗","c":["芭蕉为庵世所知，谕人生灭无多时。","春风方抽绿罗卷，秋雨便折青瑶枝。","丛茂如云盖有自，身飘著土当从谁？","畦傍筑室善取譬，叶上濡墨仍题诗。","猩红吐花粲堪数，鹅黄骈实甘如饴。","使其坚牢阅世久，敢恨迫窄逢君迟。","雨声萧萧集疏响，世路蓦蓦遭多岐。","于兹不悟佛所说，金粟如来良足嗤。"]},{"t":"杨妃上马图","f":"七言古诗","c":["华萼楼前上马时，君王忘是寿王妃。","龙颜含笑待持鞚，海棠睡美春风吹。","绣鞍娇凭翠衷冷，金灯拟跨丝鞭垂。","宫靴拍韅欲驰及，簌簌步摇危不支。","后宫窈窕千蛾眉，并乘騕袅黄金羁。","芙蓉濯露总殊妙，杂遝绮罗知谓谁？","独拥妖环何所之，联翩欲向华清池。","双龙啮膝踏花去，锦香覆满红燕脂。","从官车骑空瞻望，并肩私语行迟迟。","行毋迟迟日已西，渔阳铁骑崩云追。","才出都门便别离，千载形迹令人悲，再拜能忘臣甫诗？"]},{"t":"九马图","f":"七言古诗","c":["西风原野汗血驹，或踶或齧或惊驱。","龁草饮水秋气肃，追风抺电神情苏。","一匹滚尘一匹逋，两匹交颈如城乌。","其馀五匹总殊绝，八龙溢一崩群驽。","为问何时脱羁靮？","肆行如云从所适。","仰首斜阳嘶啮膝，一似逢人诉胸臆。","自穆西归遭汉家，不辞低头驾鼓车。","渥洼水深龙种在，玉关西望空咨嗟。"]},{"t":"王时进梅屋","f":"七言古诗","c":["张髯讲道吴王城，听受不懈惟王生。","读书折旋梅花侧，冷香吹入吾伊声。","仙芸岂是辟蠹草？","古苔终开挂凤英。","春融太古有积雪，风度曲阑糁飞琼。","生于此时读书处，正值何逊吟诗成。","岂应娟娟旧时月？","独留疏影当窗横。"]},{"t":"题画","f":"楚辞体","c":["抱琴船头为谁鼓，满江秋声荻花浦。","鲸鱼出听掉尾声，曲终鸿雁起江浒，帝子降兮木叶下。"]},{"t":"除夕","f":"七言古诗","c":["今日岁徂灯火明，欲雪未雪云冥冥。","贫家夜有轹釜声，十年飘泊吴王城。","安知节序儿女情？","不眠坐数长短更。","但有榾柮煨砂瓶，煮茗亦得尊前倾。","檐冰铮然向阶落，北邻笙歌厌杯酌。","丈夫虽贫气不索，此意莫令羁旅觉。"]},{"t":"汝阳张御史死节歌","f":"曲","c":["张御史，骂贼死，国忠臣，家孝子。","忠义国家培植来，白日照耀黄金台。","此身许国誓不二，不信白骨生青苔。","近者汝阳妖贼起，挥刀杀人丹汝水。","侯指头上獬豸冠，掌柱乾坤立人纪。","侯颈可断身可捐，义不与贼同戴天。","眦裂齿碎加愤怒，发直上指目炯然。","贼刀入口钩侯舌，舌断含糊骂不绝。","孤忠既足明丹心，三年犹须化碧血。","颜平原，张睢阳，一日虽短千载长。","人谁不死死忠义，汗简至今名字香。","朝廷易名赐庙食，人谁无心应感激？","坐令忠义销凶邪，凿井耕田歌帝力。"]},{"t":"沈孝孙孝感行，为谢医沈日新","f":"曲","c":["吴东门，葑泥千顷曾无根。","舟行滉漾渺无际，天水日夜相吐吞。","太平日久、人烟聚落散布洲渚上，绳擉网罟往往成人村。","沈仲说父、奉其高年之祖母，避喧却扫于此安晨昏。","说也不惟、文行一如李令伯，零丁孤苦、形影相依惟此祖与孙。","祖母今年九十岁，十年三蒙赐帛恩。","孙扶母出拜君命，能无芳鲜列酒樽？","阿奶喜欢、一一为孙加啖歠，便出泄泻腑脏如雷奔。","耄龄久衰元气薄，数日不复欣盘飧。","说忧形于色，苦形于言。","东吴世医沈君日新父，与沈世契、如水有委则有源。","新至切母脉，察母虚实寒与温。","谓非药可疗，精凿曾经腊水浸，中有谷气可以回脾元。","作麋饮母病良愈，说也乐甚，再拜谢新难具论。","嗟哉说与新，时之人，孝如说、艺如新，皆可敦薄俗、厚彝伦。","只今圣王敷五教、举逸民，一朝徵车轰动龙伯国，陈情有表应更语谆谆。","新也上医国固有道，说也孝感、可以假上帝通神。","明是谓同姓，不减骨肉亲。","二子孝与艺，流布千秋春。"]},{"t":"虚靖天师大道歌","f":"曲","c":["千峰秀攒龙虎山，学仙之人住其间。","时乘飞驭下人寰，主掌符箓尸神奸。","虚靖维出千载后，道风契天高莫攀。","如网有纲枢有环，足以立懦而廉顽。","岂徒风霆走禀命？","政使仙圣皆承颜。","大道甚夷民自艰，大道甚经民自孱。","天师兴歌一哀唱，只在身中无往还。","吁此血肉块，成坏等草菅。","气归元海便无极，箭射虚空真等闲。","无何虞赵二公辩方始，无乃七圣皆迷、所见才一斑。"]},{"t":"碧海谣，赠洪尊师","f":"曲","c":["我逢碧海之仙人，为赋碧海之仙谣。","霞光楼观、不在东瀛大海外，煌煌紫芝一年三秀，近在计筹之山椒。","山椒真人号南谷，乘云累侍通明朝。","其言皇帝王霸若指掌，圣心倾泞、如以水沃焦。","白云那知紫极贵，归休林壑殊逍遥。","草衣木食甘应世，土阶茅茨或梦尧。","坐致公卿贵人、北面拜稽首，真人眼空四海瞪泬寥。","于时大弟子，独称薛与姚。","洪君之家在天目，百年乔木风霜凋。","时从真人问道岩谷里，暑时日烁石，寒时雪齐腰。","道成真人驾鹤去，山头每每闻吹箫。","于今三十载，海远天迢迢。","先辈仪刑渐沦落，何以使我鄙吝消？","骑牛青林躬耕苦日短，钓鳌碧海欲往嗟路遥。","别来几度水清浅，相逢鬓发俱飘萧。","吴王城中暍欲毙，拟渡碧海心旌摇。","便欲乘槎共君去，问君登真之要诀，分君不死之药苗。","万一天风引舟便，劳君远举云旗招。"]},{"t":"送木善副使任古杭宣监","f":"曲","c":["昔者雪山大沙门，道如日月行乾坤。","属法王臣俾外护，言虽已远如生存。","爰自西来东震旦，护法孰如我皇元？","统以内外宣政院，官僚皆选宰辅尊。","公为院副秩二品，横金厌冷腰犀温。","大江之南地万里，僧之贤愚难具论。","公以宪监暂居此，摩尼珠照浊水源。","我知公继相业大，召登庙堂扣天阍。","太平勋业可坐致，岂但安禅阐教报佛恩？","异时丹青画麟阁，知是忠武鲁公贤相之诸孙。"]},{"t":"觱篥吟，次赵季文韵，赠老伶杜宽","f":"曲","c":["吴王故宫天早秋，谁吹觱篥城南楼？","一吹风生鹔鹴裘，再吹何人敢伊优？","曲终引气如刀锼，龙笛凤笙皆不侔。","五音喷薄一吸收，玉关泪落定远侯。","不独壮士皆回头，杜伶何来自中州。","目睫每射车前牛，不以伎业寒飕飕。","妙吹觱篥冠名流，嚼宫喷徵无时休。","巧如春莺转晓簧舌抽，歘如饥鹘啸树呼高飂。","惨如国殇举燐、精灵夜相求，划如雌龙挟雨、归吟百丈湫。","纬嫠与爨妇，听终各自愁。","为问竹枝芦叶、若为写出秦青讴？","四座皆感叹，何如谢安石，素抱苍生忧。","且复弹丝弄竹，少为东山留。","我愿谢公上廊庙，任臣邻掌调燮锵琳球。","一鸣箫韵下威凤，和乐雍雍闻九丘。","毋但谣觱篥，妙语高浮浮。","功成拂衣沧海上，仙人并辔骖螭虬。","却怜江潭憔悴者，悲世迫隘赋远游。"]},{"t":"李早马图","f":"曲","c":["外甥似舅明昌帝，取法宣和尚工伎。","李早画马供奉时，画院森森严品第。","冀之北土马所生，早也想见房星精。","遂令龙媒出毫素，侧胸注目疑嘶鸣。","纨扇画三骑，郎君峭鞍辔。","窄衫绣襮四带巾，靴尖曾踢中州碎。","紫绒军败祁连山，金钿玉轴仍南还。","好事空馀扇头马，至今拂拭尘埃间。"]},{"t":"离鸾曲，为贞妇徐夫人作","f":"曲","c":["鸾孤飞，凤不归，百年虽远情依依。","请弹离鸾曲，秪愁听者哭。","夫死南征儿尚乳，对镜离鸾泪如雨。","大名城里千家杵，不歌不相私相语。","为问嫠之哭，月上斗横屋。","儿啼欲乳梦夫归，金创在骨血满衣。","夫妇忠贞两不遗，匹如鸾凤参差飞。","毋云青天远，千古令人览德辉。"]},{"t":"题桐华烟卷","f":"曲","c":["桐始华桐花，开向荆溪之水涯。","溪声长绕孝侯庙，桐阴尽覆吴生家。","吴生家藏烧墨法，传自李潘久益嘉。","瓦沟爇膏火，蕴灺穗结葩。","日扫桐花之烟三万石，鬼物守护无疵瑕。","千杵万杵白兔臼，麋鹿捣胶无夜昼。","制成龙香古圭璧，玉刚金精石同寿。","奚老然松松化石，潘痴坐井井裂甃。","二子却扫桐花烟，生也与之谁后先？","墨成飞上通明殿，红云一朵捧宫砚。","试之漆黑劳磨研，吴生姓名等潘李，肯让诸蒲先著鞭？"]},{"t":"赠薛相士","f":"曲","c":["君不见会稽杨廉夫，醉吹铁笛声呜呜。","又不见虎林张伯雨，灵石溪边待轻举。","二子道异出处殊，长歌短吟意则俱。","薛生相人两眼耀流电，二子喜之皆赠以所制之诗书。","诗如于阗璊玉装剑璏，书似昆吾宝刀切琳腴。","生矜袖中有明月，出以照我白髭须。","我须日加白，我面岁增黑。","笔砚惭久芜，江湖厌为客。","生工鉴人知我者，虞翻骨屯由命也。","儿痴家贫四壁立，谁为老韩念东野？","生见张杨烦寄声，老来何处堪归耕？","珠藏深渊剑在匣，夜夜空谷腾光晶。"]},{"t":"赠翰古清","f":"曲","c":["虞公借榻宗镜堂，四众乡仰不暂忘。","古清上人独见取，赠以金薤之琳琅。","公时目眚视贸贸，文成欲写难成行。","殒星著纸废属读，风襟露带斜低昂。","中言上人善幻化，神龙千丈一钵藏。","蜿蜒委蛇各有态，擘云掣电金蛇光。","海涛翻山霹雳碎，怒捲河汉如壶浆。","世人蒿目不敢觑，师独摩抚如驯羊。","神膏点鳞翠鬣舞，金篦刮瘼星芒张。","珊瑚千树宫室秘，献以耆婆未睹之药方。","师哀其诚为摹写，风旗雷车雨脚霶。","点睛未了便飞去，砚坳有墨空淋浪。","愿师骑之上帝都，为问苍生谁短长？","凫眠鹤翥且莫辨，伽那定里松花香。"]},{"t":"岩栖仙人歌","f":"楚辞体","c":["彼仙之人，与神为谋。","舒啸烟霞，放浪林丘。","以六合为指掌，以千岁为春秋。","瞪霄汉之空碧，渺白云之孤游。","疏星向曙目光炯，赪玉映雪肌肤柔。","方骑阆风谒绛阙，又采瑶草过沧洲。","仙之人兮欲擅一壑美，匪迟徊兮此淹留。","傍置素琴不复鼓，得非与世方同忧？","龙蟠青藜杖，花落绿绮裘。","岸巾不挂壁，翠发风飕飕。","正研思虑探道奥，金匮石室非难紬。","想应误骑斑龙堕谪籍，于以辅相圣主福齐州。","颠崖苍生性命悬一缕，可但独乐身夷犹。","仙之人兮须为谢安石，莫学王子猷。","谢公廊庙上王郎，涧之幽穷而成仙。","达卿相君家，子房出处真其俦。","功成拂衣江海去，笛声尚殷岳阳楼。"]},{"t":"槟榔木拄杖歌","f":"曲","c":["海南草树四时绿，至刚独有槟榔木。","刻作仙人九节杖，昆吾之刀削玄玉。","吴人沈傅师，腹撑书与诗。","跫然念我老，赠此珊瑚枝。","入手岂独扶持力，老蛟虽瘦铁作脊。","何况提携指爪间，玄冥侧身避正色。","朝敲邻扉看竹去，邻翁指示三叹息。","此枝曾被猩猩攀，酒痕尚留枝节间。","灵药结作鸡心核，蛮唾噀成花乳殷。","老夫方将东入海，撑拄残骸谒真宰。","就中可有安期在？","杖头挑得枣归来，分饷傅师寿千载。"]},{"t":"松风吟","f":"曲","c":["昔者谷仙之真人，曾谒世皇通明殿，殿上赐坐言谆谆。","以为皇王帝霸，不殊冬夏秋春。","紫极虽贵，白云难亲。","翩然归卧计筹峰下通玄馆，日听松风不异大韶乐，自谓身是葛天民。","松风晴吹东日上蓬山，阁外五采云霞新。","日方西倾月复白，松风吹涧壑，不著人间一点之埃尘。","细而笙竽间奏有馀韵，大而海涛怒鼓翻龙鳞。","真人卧起食息听不厌，自谓轩辕张乐、湘灵鼓瑟同天真。","有时雨雪黯惨之寒夜，有时花柳明媚之芳辰。","松风不吹樽俎澹，松风不吹肌骨皴。","真人于此时，漱咽太和朝玉宸。","撼屋松风三日吹不醒，安知便以神为马、尻为轮？","飞度蓬莱弱水三万里，众真欢言归何晚，坐吟松花屑粉沾冠巾。","于今三十五寒暑，天根月窟来往长频频。","济济山中学仙侣，或跨鸾凤骖骐麟。","辛钘范蠡谩师友，南郭颜成谁主宾？","善听松风不以耳，善御松风不以身。","真人有道传不朽，千古万古无缁磷。"]},{"t":"自怡歌","f":"曲","c":["缅惟陶隐居，高卧松风楼。","太平晋主特延聘，麟凤肯向人间游。","试询山中何所乐，白云与我同悠悠。","当时江左难将作，三纲坠地民风媮。","所以自怡者，惟答白云盈陇头。","至今称其高，疑是神仙流。","东吴阿翁贞白裔，不遂鞅掌干王侯。","国政虽未斁，黎氓却怀忧。","忧民之责非预韦布谋，所以摆脱世寰声势利，惟与白云为伴俦。","刍豢岂足适吾口，绮绣何以开吾眸？","澹然白云相近处，那知倚门肮脏风马牛？","热鏊翻饼紫缬赂方州，车轮括颈宰执图小秋。","周为胡蝶蝶为周，天下之乐莫若怡云优。","个中谁觉察，身心亦相雠。","好如司马之独乐，知者良寡昧者稠。","吾聆此语，奚翅钧天广乐锵琳球？","老发雪种种，戒得当自脩。","便欲陪杖屦，与云同去留。","山中自怡者，慨然许识此意否，慨然许识此意否？"]},{"t":"悲歌，寄呈刘学斋相执，王可矩、张德昭二尚书，周雪坡大监，王本中经历，贡吉甫司业，宇文子贞助教，危太朴待制，贡泰甫授经，陈元礼孝廉列位","f":"曲","c":["天星曾照遂昌山，人家隐约木石岩峦间。","贞元丞相有支裔，避地东入浙，甘与猿猱麋鹿老死不复还。","五季闽王郑光禄，至今拱木斩伐后，尚尔青珊珊。","使不念乡井，俯仰应厚颜。","其如贫病日零落，每企予望涕泣长潸潸。","侨吴三十载，惟馀此心在。","岂惟读书老无成，但觉出门俱有碍。","三儿两病一凡劣，四体三完百崩败。","贷粟方炊薪水艰，僦屋屡迁家具坏。","文章出售有谁收，书籍纵沽无可卖。","此心独存何所似，夜夜长虹发光怪。","青云故人禄万钟，不割少许裨饥穷。","忍令江南秋雨夜，颓垣腐草啼寒蛩。"]},{"t":"李遵道海岳图","f":"曲","c":["李黄岩，疏眉瘦体满臆秋崭崭。","似厌分符涧谷底，折腰督邮面皱须毵毵。","竟骑鲸鱼上天去，帝悯人间留不住，乃令笔底飞墨如云雾。","王维郑虔本有素，早年临摹米颠海岳图。","黄岩非有颠非无，庵空月落山木拥，是中疑有穷猿呼。","二子风流俱不泯，宝月夜夜生珊瑚。"]},{"t":"赵松雪人马","f":"曲","c":["王孙昔骑天厩驎，貌得名驹并圉人。","羲台路寝风日美，绣勒锦鞯花柳春。","吾闻冀北之野，每以谷量马。","骏骨千金古来寡，世皇骑之一天下。","鞭笞四海入袅蹄，亿兆俯伏听鸣嘶。","如何频年顿失之，对画令人双泪垂。"]},{"t":"黄公望山水","f":"曲","c":["姬虞山，黄大痴，鹑衣垢面白发垂。","愤投南山，或鼓袒禓。","勇饥驱东阁，肯为儿女资。","不惮北游行万里，归来画山复画水。","荆关复生亦退避。","独有北苑董营丘，李放出头差可耳。","颜仙种术茅公山，喜得此卷开心颜。","句曲千岩万壑纵深秀，何似卷舒只在咫尺间？"]},{"t":"活死人窝，为番阳胡道玄赋","f":"曲","c":["我尝梦登天，身乘帝青云。","下视六合大，死人何纷纷！","尸行鬼走不知丑，天跳鬼踔无由分。","首戴髑髅蒿两目，肠悬题凑空孤坟。","自谓策神智，可以干明君。","自谓雕纂组，可以成华文。","自谓昭旗常，可以铭前勋。","形如枯株心强活，气如湿灰耳强闻。","哀哉腥腐窟，何以能超群？","天孙为余言，此皆不足云。","累累白骨成飞尘，安知中有不死人？","眉厖喉结目如电，挥呵风雨走百神。","塌额玉陛下，自称小兆臣。","臣之形骸与众等，久断荤血腐肉皴。","言臣不死诚谬妄，固有不死丹元君。","丹元君，在何处，泥丸真人且延驻。","一曲鸾笙五百年，死人窝里翻身去。"]},{"t":"送性僧游径山","f":"曲","c":["忆昔苕溪登径山，童孩无识空跻攀。","但见五峰削玉倚天外，兼闻众木戛乐下云间。","振威何人喝石裂？","行脚有僧挑月还。","神龙依禅井水立，杜鹃啼血春花殷。","孤烟中分白窈窕，一雨忽洗青崭颜。","何时复至旧游处？","行踪应有苍苔斑。","愿从师去不可得，起看萝月空湾湾。"]},{"t":"雪巢","f":"曲","c":["太古有积雪，不在西蜀西。","西蜀之西云山远，斲冰千仞难攀跻。","岂如界溪之上肃侯宇？","虚室生白皦于楮。","正犹积雪太古前，表里空明堪中处。","其处其谁世寡俦，纯净不涅缁尘羞。","素履恒因积后见，冰潢夜转银潢流。","遂疑巢居葛天氏，不在木末并山头。","三辰惜明启牖户，九霄排云达遥路。","吴天月明日将曙，铜盘盛得金茎露。","借问脩梁初举时，见者喜气盈芝眉。","巢成定产九苞凤，我老为赋卷阿诗。"]},{"t":"陈履元画玉山草堂","f":"曲","c":["故人陈孟公，辞如春云气如虹。","画法师海岳，山如骞鹏树如龙。","骑箕上天二十载，有子齇鼻画极工。","惊蛟嘘云海浪白，离鸾照水岩花红。","皱鳞张鬐耸郁涧底松，中有一亩幽人宫。","石床支颐睨飞瀑，意远欲托冥飞鸿。","我欲从之不可得，青山万叠金芙蓉。"]},{"t":"赵松雪画马","f":"曲","c":["地用莫如马，壶头竟何施？","寒风善相不假式，何必郭家口齿谢家鬐？","神驹龙变如何按式取，譬之图面八骏令人嗤。","君不见房星精飞光，夜流拽练明。","汉家都厩尽凡骨，冀之北土龙方生。","儿能引弓射乌鼠，便解骑过宛王城。","玉堂学士亲眼见，貌得风蹄耀流电。","山人半世只步行，髀肉何曾识鞍韅。","每每作诗题马图，千金骏骨世所无。","人间空费粉墨摹，玄黄牝牡真成诬。"]},{"t":"高房山墨竹","f":"曲","c":["高侯胸中渭川之千亩，家居房山未必有如何。","文章政事之暇日，能为此君图不朽。","想当飞墨时，苍龙投砚池。","山雨急洗琅玕节，海月静照珊瑚枝。","自侯骑箕上天去，浮世茫茫水东注。","千秋万古房山云，载拜为侯赋墨君。"]},{"t":"倪元镇古木竹石","f":"楚辞体","c":["云林子，外生死，解内敬，为天使。","带经而锄倦即休，亦复拈笔为林丘。","树枝鳞皴崖石幽，若有人兮在空谷。","招之不来兮，云惨瘁以令人愁。"]},{"t":"沈仲说画树石","f":"曲","c":["风流沈传师，浩荡江海姿。","默庵岂诚默？","开口谭书诗。","兴来捉笔画树石，溪深岸高浪波白。","豪端无非篆籀法，折铁中郎此其式。","世人贵耳贱目者，于此却令三叹息。"]},{"t":"稽康柳下锻图","f":"曲","c":["何所闻而来？","不妨柳下锻。","何所见而去，魏鼎不复爨。","哀哉志士千古心，有锤弗锻跃冶金。"]},{"t":"江乡捕鱼图","f":"曲","c":["人言东坡谪居海上时，顾见渔钓之家乐嬉嬉。","问其生涯、烟波万顷舟一叶；","问其日给、虾蟹小鲜日三炊。","有时大鱼入网即沽酒，有时顺风张帆即解维。","不知朝廷尊严，百官侧枕听鸡起；","不知行役戴星，出入世途愁险欹。","篷窗齁齁子女睡，竹笛呜呜朝暮吹。","坡闻其言惨不乐，我身何有恒百罹？","瘴海南浮天接水，家乡往往梦见之。","何如此渔者，生不触祸机。","粗衣粝饭既饱暖，高盖大马空奔驰。","我观此图重叹息，无乃有似，坡翁所见画入无声诗。","金绯贵官一射猎，渔钓江湖劳梦思。","投毫写图意可见，一舸秋风双鬓丝。"]},{"t":"送峡州何学正","f":"五言律诗","c":["夜雨西陵树，春风燕喜亭。","学宫资裁正，士类仰仪刑。","天险开三峡，人心系六经。","哀猿月中啸，莫作异乡听。"]},{"t":"送泉州蒙古学正","f":"五言律诗","c":["王制严心画，臣工重古人。","朝廷政典大，岭海学宫新。","番舶槟榔唾，邮签荔子尘。","方言若翻译，谁与计偕陈？"]},{"t":"送白主簿二首 其一","f":"五言律诗","c":["牢落慈湖馆，于今二百年。","闲居仍悯已，解易尚成编。","吾道乾坤大，斯文日月悬。","何时甬东路？","入邑拜前贤。"]},{"t":"送白主簿二首 其二","f":"五言律诗","c":["簿领慈溪县，遥知傍海漘。","熬波官赋急，扶犊野农淳。","船发帆樯晓，烟明岛屿春。","每嫌凤栖棘，咫尺是青旻。"]},{"t":"次韵虞学士赠赵伯容","f":"五言律诗","c":["王孙有仙骨，梦断郁轮袍。","候火温丹鼎，吹笙醉碧桃。","鸟母双蓬鬓，鹓雏五色毛。","人间既腥腐，青海乐游翱。"]},{"t":"寄张宣慰","f":"五言律诗","c":["此老悬车日，颜丹发尚玄。","由来行乐处，须及未衰年。","令子工为政，诸孙雅尚贤。","固应歌舞地，长见月初圆。"]},{"t":"贞逸处士","f":"五言律诗","c":["处士生无字，端居代有人。","飞书表贞逸，闭户乐清真。","生意萱花晓，恩光棣萼春。","悬知束帛聘，侧席待天民。"]},{"t":"送陆秀才","f":"五言律诗","c":["出鼓江湖枻，来餐杞菊苗。","道方行沃壤，舟已问归潮。","水浦鱼初上，春城雪未消。","思君好溪水，乡梦夜迢迢。"]},{"t":"义兴岳夫人挽歌词","f":"五言律诗","c":["道岂污隆易，身由洁素全。","柏舟凌黑浪，蓬首戴皇天。","木拱终同穴，兰摧不异阡。","何人纪贞烈？","留取姓名传。"]},{"t":"朱泽民画","f":"五言律诗","c":["窈窕溪桥路，阴森枫树林。","岸随青嶂转，家在白云深。","画史分明意，山人去住心。","劳形何日已？","于此欲投簪。"]},{"t":"赠永嘉高生","f":"五言律诗","c":["高生永嘉秀，秀也实南金。","学启麟经秘，雏生凤穴深。","浪花迎客棹，霜叶变枫林。","异日巍科掇，秋期又盍簪？"]},{"t":"送范山长","f":"五言律诗","c":["晓色冯公岭，春风庆朔堂。","亲庭白云外，书院碧山傍。","雀啄飞花柳，鸠鸣结椹桑。","诗书有世泽，簪笏继朝行。"]},{"t":"昆山石","f":"五言律诗","c":["昆冈曾蕴玉，此石尚函辉。","龙伯珠玑服，仙灵薜荔衣。","一泓天景动，九节涧苗肥。","阅世忘吾老，苍寒意未违。"]},{"t":"虞侍讲书乃祖丞相雍公诛蚊赋","f":"五言律诗","c":["父作更生灵，儿为命世英。","西州睹威凤，南国剪长鲸。","不厌朝廷小，终扶日月明。","诛蚊赋重录，妙墨冠时名。"]},{"t":"徐良夫耕渔轩游题","f":"五言律诗","c":["幽馆夏初度，清林暑气中。","开轩对流水，坐石待薰风。","花落乌巾侧，鸟啼山几空。","耕渔者谁子？","散发奏丝桐。"]},{"t":"次韵宋春卿","f":"五言律诗","c":["闲贵堂前路，于今二十年。","美人黄土后，废址绿芜边。","顾我知何已？","唯公独岿然。","春风吹杖屦，犹复侍周旋。"]},{"t":"挽章德懋","f":"五言律诗","c":["博士衫才绿，书生鬓已皤。","艰难奈行李，契阔动哀歌。","叠窗床仍在，临池墨尚多。","郇公有世泽，春水洞庭波。"]},{"t":"赠薛相士","f":"五言律诗","c":["子有唐生术，谁如范叔寒？","知无狼顾骨，可有鹖皮冠？","野日晴犹懒，春泥晓未乾。","多君远相顾，不用画灰看。"]},{"t":"送何景文","f":"五言律诗","c":["郡国推何武，江湖光郑虔。","世儒方酝籍，诗律尚清妍。","宰相才难得，文章妙莫传。","归耕钓台畔，早寄白云篇。"]},{"t":"鍊雪轩","f":"五言律诗","c":["谁鍊红炉雪，晴云几面旋。","六花吹作乳，两腋欲成仙。","苍璧龙鳞舞，松花蟹眼圆。","如何鬻白石？","一味舌头禅。"]},{"t":"飞龙亭","f":"五言古诗","c":["先帝潜龙日，幽人待鹤时。","青山频望幸，琳馆暂来娱。","宝篆黄金鼎，恩波白玉卮。","天开六朝地，花发万年枝。","闪闪前星夜，汪汪湛露私。","远符天历凤，先协石龛龟。","稽古开廷阁，翻经出讲帷。","方蒙宣室召，忽抱鼎湖悲。","旧邸梅花落，新亭柳线垂。","至今思沛感，时或下云旗。"]},{"t":"送徐山长勉之赴慈湖","f":"五言古诗","c":["见说慈溪县，先民有学宫。","心源推自得，已易竟谁通？","论道非人异，朝宗到海同。","朝窗梅蕊白，夜馆烛花红。","遵渚三更雁，吟秋四壁蛩。","横经山色里，觅句雨声中。","官况毡何冷，词场笔最工。","棘围还待子，金榜日华东。"]},{"t":"送李举人克明任教职","f":"五言古诗","c":["职教同时雨，郎官等列星。","吴区都水监，闽国道山亭。","两地头逾白，诸公眼为青。","身名金玉质，文采凤凰翎。","鼓枻辞江郡，携书入汉廷。","河山秋肃肃，宫阙晓冥冥。","夜月鸿遵渚，秋风马在坰。","李峤初梦笔，刘向老传经。","朴棫材千尺，菁莪翠一庭。","天边期中鹄，囊底任枯萤。","归路梅花发，长歌为子听。"]},{"t":"送嵇洞玄鍊师云游","f":"五言古诗","c":["已蹑东游屩，还乘上海槎。","寻真度弱水，招子饭胡麻。","少广苍精佩，双成绿髻髽。","娱游芝作盖，服食枣如瓜。","鼍乘观初日，神虚茹幼霞。","玉笙宵度曲，金匮夙抽芽。","遂把东皇袂，来朝阿母家。","初平羊已化，中散虱空爬。","剑蚀缑仍结，尊空石漫洼。","归期定何日？","夜夜卜灯花。"]},{"t":"挽钱翼之","f":"五言古诗","c":["字法勤书史，年劳起校官。","如何管城子？","竟老鹖皮冠。","句积诗囊重，心投酒斝宽。","刻深吴下石，名蔼楚卿兰。","梅福身垂老，虞翻骨未寒。","佳儿继述作，留与后人看。"]},{"t":"挽虞彦高","f":"五言古诗","c":["苕水横经日，长洲筦库时。","玄霞散髭鬣，白雪吐言词。","自分儒绅拙，宁知委吏卑？","袖笼生物手，笏拄看山颐。","返老梁溪澨，悬车锡麓陲。","温言恒侃侃，孺乐更怡怡。","竹色宾阶润，花阴户屦移。","入闽求古刻，踰浙致名师。","夜雨连书屋，春风动讲帷。","扣舷吴子国，鬻茗李绅祠。","政以孤踪澹，谁令二竖持？","古心空似月，里鬓已如丝。","白日诚难挽，皇天不憖遗。","士林纷雨泣，絮酒谅神知。","丹旐霜风惨，青林磴道危。","可无千字诔，因赋八哀诗。"]},{"t":"送刘廷美待聘","f":"五言古诗","c":["文皇南面日，刘楚北游时。","抗疏三公府，高名四海知。","近臣推得士，公论果无私。","坐置昌平策，归寻后土祠。","仲容为侄好，王述岂人痴？","骥子难笼络，鹓雏足羽仪。","气纡商女怨，赋解洛神悲。","淮左辞攀桂，商颜罢茹芝。","长裾今已曳，好爵固应縻。","送子难为别，西门折柳枝。"]},{"t":"送杨季常山长","f":"五言古诗","c":["杨子谭经处，吴公学道祠。","宫墙红靡靡，庭筱绿差差。","演迤诗书泽，冲融雨露私。","草玄心独苦，稽古力难裨。","二载平生学，诸生去后思。","简书犹用试，匠石讵能遗？","雾豹方深隐，云鹏岂后时？","会看清白吏，勋业著常旗。"]},{"t":"挽潘祥卿","f":"五言古诗","c":["已佩官箴肃，人推吏议精。","笔锋回雅道，经术谳疑情。","孝悌居无忝，公廉志夙成。","家移山郭住，禄代石田耕。","晚谢芜湖幕，恩留槜李城。","湖山容佚老，篷藋足逃名。","藉草抛书卷，看云把酒觥。","阳坡秋种菊，画舫夜弹筝。","既已忘荣辱，方知外死生。","巉巉墓头石，百世保庥贞。"]},{"t":"刘母丁夫人挽词","f":"五言古诗","c":["忠养儿能孝，居官不患贫。","长言远游客，兼是未亡人。","主绩机恒纺，尸饔馔必亲。","课孙裨缺学，为子款佳宾。","莲幕方图养，蓉城忽返真。","两雏悲塌翼，诸友为沾巾。","泪断枯鱼索，愁凝绣鹄茵。","佳城瘗何日？","瞻望极酸辛。"]},{"t":"奉柳太常道传","f":"七言律诗","c":["乌蜀先生双鬓丝，莼鲈江上故园思。","水光闪闪金壶墨，石理硁硁玉佩辞。","水落鱼龙秋不雨，月明乌鹊夜无枝。","名山蚤选藏书穴，趁取蒲轮未召时。"]},{"t":"送贡司业泰甫","f":"七言律诗","c":["代祀躬趋黄木湾，归朝仍缀紫宸班。","识高京兆囊封后，道在河汾户屦间。","迎日讲筵瞻凤扆，吁天经术动龙颜。","异时归窆藏书穴，好在南湖叠嶂山。"]},{"t":"送泰兼善总兵","f":"七言律诗","c":["大帅楼船过浙东，军声肃肃峭寒中。","令严虎帐中天日，威息鲸波万里风。","蛮徼尽惊戎毡白，极南遥涌寿星红。","道山宫阙多仙圣，预启瑶编录隽功。"]},{"t":"寄云南萧元帅","f":"七言律诗","c":["南望元戎玉帐寒，炎炎桂海息狂澜。","牵狮入贡金连索，骑象来朝罽织鞍。","丞相渡泸先鬓白，将军标柱独心丹。","春波涸尽思霖雨，箕毕星缠夜夜看。"]},{"t":"送许具瞻进士","f":"七言律诗","c":["纯孝渊渊许子将，身迁父柩脱烟炀。","遂登龙虎黄金榜，便绾鹓鸾紫荷囊。","山水窟中民讼简，弦歌声里昼阴长。","圣朝南面求贤切，伫见才名上庙堂。"]},{"t":"寄潘子素文学","f":"七言律诗","c":["与子同庚命不同，悠悠江海异穷通。","潜鳞易借风云力，朽蘖难论雨露功。","欲进老人圯上履，可孤焦尾峄阳桐？","河阳县里花千树，不借孤芳一朵红。"]},{"t":"次韵顾仁夫得代","f":"七言律诗","c":["君房未历金华省，潘岳犹居散骑营。","秋水红莲能自采，春愁白发为谁生？","梦惊里闬三年别，归载图书一舸轻。","野老凄凉迟吾去，更谁虚左日相迎？"]},{"t":"次韵赠完颜子中","f":"七言律诗","c":["紫诰黄麻叠绾归，棣花香里拜庭闱。","圣经教子无金埒，宪节传家有绣衣。","佳句易增诗箧重，故人难会酒行稀。","愿从菰米鲈鱼国，醉把黄花莫暂违。"]},{"t":"寄杨士可巡检","f":"七言律诗","c":["警逻深山行夕岚，日严笳鼓罢幽探。","坐中拄笏知非据，马上弯弓想渐谙。","桃叶长年思共渡，菊英何日采盈甔？","扬雄干柱华榱宅，只在辉辉北斗南。"]},{"t":"蔡孝子庐墓","f":"七言律诗","c":["三十六峰云气深，墓庐何处得相寻？","青山当户哀哀哭，白日孤光黯黯沉。","驯虎欲嘷风落石，栖乌不定月穿林。","三年泣血谁相问？","虢虢寒泉涧下音。"]},{"t":"钱道士游仙","f":"七言律诗","c":["绿发飘萧礼上玄，明皇遥隔绛河边。","香消楚泽春风佩，愁入湘城夜雨弦。","素手不将条脱赠，绮疏惟把步虚编。","西神峰顶飞霞观，小驻鸾笙五百年。"]},{"t":"栖碧亭，为华幼武赋","f":"七言律诗","c":["华家池馆堠山南，但见乔木翠毵毵。","金波影里鱼鳞屋，玉佩声中麈尾谭。","黄□□云连町疃，红飞花雨扑烟岚。","渔郎一别桃源路，回首春风雪满簪。"]},{"t":"芸斋","f":"七言律诗","c":["博士斋居芸草香，青编不复蠹鱼伤。","能穷腹里书三箧，敢望身前笏满床。","雨屋篝灯惊鹤梦，月窗展卷澹萤光。","孔门休用平生学，绿发应须佐世康。"]},{"t":"园隐","f":"七言律诗","c":["麻姑山下地仙家，谖草春深剩著花。","雊雉逐雌催刈麦，鸣鸠呼雨课锄瓜。","放歌不厌牛亲饭，对客何妨虱屡爬？","一夜南坡雷雨作，竹萌迸地蕨抽芽。"]},{"t":"宣城姚秀才弃举业，为道士于升州","f":"七言律诗","c":["娟娟月出敬亭山，曾照书声竹树间。","澹墨何须题雁塔？","扁舟先已过龙湾。","仙人观阙云端见，帝子笙箫月下还。","水驿花开笑相问，澹波谁似白鸥闲？"]},{"t":"至元丁丑夏五，宣城汪叔敬、吴人干寿道、丹丘柯敬仲、国人泰兼善同仆游天平，次往灵岩，有作奉和二首 其一 天平魏公祠","f":"七言律诗","c":["西望层峦草木青，魏公祠下拜仪刑。","经纶有策回天地，忧乐无时忘阙庭。","异代蒸尝遵典礼，故山香火下神灵。","浮云变灭知何在？","闲听松风语塔铃。"]},{"t":"至元丁丑夏五，宣城汪叔敬、吴人干寿道、丹丘柯敬仲、国人泰兼善同仆游天平，次往灵岩，有作奉和二首 其二 灵岩涵空阁","f":"七言律诗","c":["吴王宫阙草萋萋，飞阁重登意转迷。","洗砚池边云欲暝，拜郊台上日平西。","湖涵远浪千帆没，树响悲风一鹘栖。","江海鸱夷招不返，荒烟野水鹧鸪啼。"]},{"t":"送乐鼎仪归东平","f":"七言律诗","c":["岱宗高入帝青寒，策马东归不厌看。","一变便兴周礼乐，两生那识汉衣冠？","雨休树下碑仍在，云起封中玉未刊。","更上灵光殿基望，冥冥鸿鹄有修翰。"]},{"t":"送季山甫慈湖教谕","f":"七言律诗","c":["季子扬舲之甬东，慈湖应与暮潮通。","豚吹野岸杨花白，鸠食桑林椹子红。","遗老应传羲易说，先民谁继日钞功？","东吴寓叟头全白，目送孤云没断鸿。"]},{"t":"和宇文子贞见寄","f":"七言律诗","c":["别来见话幽人屋，此去当扶野老筇。","泾底鱼肥春欲上，墙阴荠嫩雪犹封。","斋庖不轹频炊釜，山屐应留屡舞踪。","它日孙依外家学，书签题墨写教浓。"]},{"t":"送林道士归温","f":"七言律诗","c":["雁荡行云生翠微，东还行李正騑騑。","松矜日老当秋发，鹤养雏成待客归。","珠斗影寒璊玉璏，绣云香积紫烟衣。","悬知夜礼虚皇罢，宴坐朝元意不违。"]},{"t":"游嘉定道院","f":"七言律诗","c":["芙蓉洲上集仙宫，环佩声闻缥缈中。","桂阁吹香天乐下，稻田疏脉海潮通。","呼龙起舞迎初日，跨鹤归来御晚风。","大药已成金鼎堕，丹光犹得兆年丰。"]},{"t":"春寒","f":"七言律诗","c":["春寒峭峭过王师，都出南门送鼓旗。","岭海鲸鲵就诛日，江湖鸿雁欲归时。","参差帆叶开溪舫，颠倒梅花落砚池。","多病杜陵头白尽，每因送客赋新诗。"]},{"t":"送葛奏差赴闽","f":"七言律诗","c":["天子分符镇七闽，元戎建旆拂三辰。","荔花蜂采千崖蜜，榕树莺啼二月春。","吏署看山时拄笏，使轺飞鞚不惊尘。","南来勾漏丹砂诀，最爱溪边白鹿驯。"]},{"t":"庐山图","f":"七言律诗","c":["浔阳郭里望庐山，日出千峰紫翠间。","烟树近同蛮井络，风帆遥认楚乡关。","匡仙抱鹤岩头放，李白骑鲸海上还。","却向画图求彷佛，菖蒲花老石苔斑。"]},{"t":"题程国表妻墓碣","f":"七言律诗","c":["太末溪头送夫婿，祝郎战胜早归来。","龙光暂漏金闺籍，鸾影先分玉镜台。","儿女泪痕宵泣血，杯圈口泽岁兴衰。","它年墓道焚黄日，铭碣悲凉首重回。"]},{"t":"陈母张安人挽辞","f":"七言律诗","c":["延陵陈母具柔慈，训子成名鬓亦丝。","楼护起家元自蚤，冯勤补衮不嫌迟。","旨甘每却熬波味，燕飨长怀剪发思。","未拜恩封先已没，后来阡表有馀悲。"]},{"t":"挽杨九玄","f":"七言律诗","c":["虎丘山下有孤坟，曾识谭经杨子云。","梦落江湖仍听雨，魂归泉壤亦修文。","家山路远听猿泪，书传香留辟蠹芸。","况有佳儿能力学，草玄犹足继前闻。"]},{"t":"宾月楼","f":"七言律诗","c":["最爱香山宾月楼，清光全得太湖秋。","鱼龙出向初筵舞，蟾兔来从上客游。","凝阁绿苔须士赋，委波金镜属谁收？","江山千古才情在，牛渚何人独献酬？"]},{"t":"知音亭","f":"七言律诗","c":["亭院日长深复深，高山流水思愔愔。","曲中别鹤啼清怨，树底薰风养绿阴。","激楚忽闻机裂帛，怀人又见冶镕金。","能言万籁无南郭，隐几形闲孰赏音？"]},{"t":"听雨楼","f":"七言律诗","c":["每爱沧江听雨眠，不应愁绝似今年。","建瓴长恐崩高屋，鍊石徒闻补漏天。","响入北廊葭菼乱，湿增傍壁薜萝牵。","白头倦客孤蓬底，尚想躬耕有石田。"]},{"t":"赵季文茶屋","f":"七言律诗","c":["萧萧茶屋傍池开，谩谩丛筠带雨栽。","窗雪晃晴鸡误唱，炊烟带暝鹤归来。","醉酒烧烛亲黄卷，静爱飞花点绿苔。","尊酒久违真寂寞，鹧鸪啼上越王台。"]},{"t":"薛玄卿鹤斋","f":"七言律诗","c":["君家少保已登云，留得青田貌后真。","乌母督仙须显驾，羽车骖乘必长人。","听经香案孤撑雪，啄菌瑶阶每遇春。","迟子吹笙明月下，丹砂乞与顶头巾。"]},{"t":"次韵寄颜元卿院判","f":"七言律诗","c":["酒尽空悬蘸甲瓢，一灯孤馆夜寥寥。","雁寒犹下沧洲宿，地暖何由重雾消？","长笛一声推赵嘏，衮衣三世属文饶。","看云早晚摩天翼，瞥尔青云万里遥。"]},{"t":"寄泰兼善总制","f":"七言律诗","c":["征凤鲜于专节制，戮鲸王式任偏裨。","长江谩击中流楫，落日方悬大将旗。","夜泣寒机嫠掷纬，朝妆明镜女扬眉。","丈夫身在难乾没，三秀煌煌是紫芝。"]},{"t":"和吴宗师，寄张贞居","f":"七言律诗","c":["齐老堂前烟树空，真人锡类坐神宫。","一缣今赉高年帛，重壤惊回秃发翁。","琳馆花残春欲雨，石坛松老夜多风。","遥思问道崆峒处，都在衢尊盎盎中。"]},{"t":"次韵薛真人贺吴宗师寿辰","f":"七言律诗","c":["臣工袒割紫鳞肪，辞藻辉飞白玉堂。","五色云中扶日毂，九霞杯里酌天浆。","又从禹范开皇极，重拾尧蓂纪岁阳。","古桂长承新雨露，绵绵根柢发天香。"]},{"t":"寿春官达郎中","f":"七言律诗","c":["清油幕下紫薇开，身总群纲儗上台。","桂海已闻京观筑，越裳还见贡琛来。","诗书未与秋摇落，刀尺难从世剸裁。","廊庙栋梁须致用，贞松合抱是良材。"]},{"t":"次韵王季野北归二首 其一","f":"七言律诗","c":["黑发黄髯万里归，腰如开国待犀围。","楼前花似琴台发，江上鱼如丙穴肥。","蛮井远民茶税急，槐阴燕席酒觥飞。","名勋莫负传家笏，六尺青云立绣衣。"]},{"t":"次韵王季野北归二首 其二","f":"七言律诗","c":["公子承恩日下归，小山堂上锦香围。","百壶写渌方论醉，五鼎熬肪不厌肥。","听瑟池鱼冲浪出，寄书笼鹤傍云飞。","茜袍色映轻裘好，为是夫人手制衣。"]},{"t":"岁暮感事","f":"七言律诗","c":["岁除风雪苦阴寒，民庶逋租悉系官。","破荡未充狼虎欲，系累只作马牛看。","何人肯破杨城械？","有客空弹贡禹冠。","上力已穷民力瘁，腐儒头白泪阑干。"]},{"t":"范魏公祠","f":"七言律诗","c":["白云乡里魏公祠，翼翼烝尝荐奠时。","功盖百年书史载，道求千古圣贤知。","山侵虎穴盘风磴，石拔鲸牙插羽旗。","更上高亭望城邑，义田秋实正离离。"]},{"t":"龙门","f":"七言律诗","c":["龙门岞崿倚天开，点额神鱼几度来？","云起区中成五色，星从阙角见三台。","更无铁限嗤山鬼，可有金铺上石苔？","李范党同勋业异，御车千古意悠哉。"]},{"t":"天池","f":"七言律诗","c":["立石如云不待鞭，兀临池水看青天。","下潜灵物疑无底，傍溉山畦似有年。","刺水翠苗霜后在，舞风珠树月中悬。","太湖万顷应凡浊，閟此泓渟一勺泉。"]},{"t":"寄郑长卿","f":"七言律诗","c":["吾宗自昔有升沈，况复姬嬴远至今。","世讶孙枝发枯蘖，人推祖德返遗金。","螭头未必云萦佩，谷口何嫌雪满簪？","自恨衰年多病苦，药囊时乞细探寻。"]},{"t":"寿李廉使","f":"七言律诗","c":["立秋三日是生申，督饟功高海若驯。","金节已悬岩下电，绣衣仍应日边春。","久从隶古森波磔，复向心源揖圣神。","野老愿留吴下住，一新漕政答鸿钧。"]},{"t":"寄于彦成高士","f":"七言律诗","c":["文锋久淬鸊鹈膏，鞍甲藏身百战鏖。","王簿宅前春载酒，李绅祠下醉挥毫。","乡关未觉东林远，光焰终如北斗高。","儒老感君难报称，黄金随力铸韦皋。"]},{"t":"送郝遵道北归","f":"曲","c":["汴河千里雁南飞，吴下孤帆又北。","归竹素残编无世味，蒯缑孤剑有星辉。","岧峣使节弓旌近，迤逦神州草木稀。","想见琼轩恭对日，黄金台上雪霏霏。"]},{"t":"次韵刘宪副春日湖上有感五首 其一","f":"七言律诗","c":["庾信哀多赋漫成，江南文物久晨星。","市衢火后蒿横目，民舍春来草满庭。","浪齧湖堤官柳尽，沙填江浦夜潮腥。","归来何异辽东鹤，只有西山慰眼青。"]},{"t":"次韵刘宪副春日湖上有感五首 其二","f":"七言律诗","c":["湖水西边旧是家，春风绕屋种梅花。","传闻故老谈前日，爱教仙人服幼霞。","鹤老离巢松化石，鸾孤照水竹穿沙。","只今重到经行处，憔悴萧郎两鬓华。"]},{"t":"次韵刘宪副春日湖上有感五首 其三","f":"七言律诗","c":["潮落空城谁重过，犹馀里耳听鸣珂。","襄阳耆旧知谁在？","江左风流不厌多。","自见石麟眠枳棘，长闻蜀魄叫松萝。","野梅开尽西湖雪，万斛春愁奈尔何。"]},{"t":"次韵刘宪副春日湖上有感五首 其四","f":"七言律诗","c":["湖水荒荒寒食天，相逢犹话国初年。","红楼夜唱花间席，翠管春吹月下船。","玄圃自应留富丽，湘云谁为惜清妍？","可怜头白归来日，井邑凄凉蔼白烟。"]},{"t":"次韵刘宪副春日湖上有感五首 其五","f":"七言律诗","c":["青苔寺里客来稀，乌石冈边僧自归。","金雁嘈云春不去，玉鱼冲雨夜曾飞。","出门每歌月皎皎，制佩莫惜芳菲菲。","人世何由比金石？","嗟我欲把东皇衣。"]},{"t":"次韵钱伯行游仙诗二首 其一","f":"七言律诗","c":["海定初风湛绿罗，仙人词藻寄来多。","贯珠音在云谁遏？","琢玉文成手自磨。","霄汉画桥尝有会，昆崙黄竹漫成歌。","可怜人世书裙手，池上犹笼道士鹅。"]},{"t":"次韵钱伯行游仙诗二首 其二","f":"七言律诗","c":["轧轧青牛拟度沙，煌煌白兔岂无家？","肉生徐甲符难秘，斧钝吴刚桂始华。","谛授宝书盟刻玉，醉离瑶席舞传葩。","竹宫望拜真痴绝，日日韶光在景霞。"]},{"t":"送章心远道士入闽兼简杜清碧先生","f":"七言律诗","c":["风日晴缫杨柳青，翩然独鹤过南溟。","山中每忆罗公远，海上重逢武达灵。","榕叶拥云山似簇，蛎房烹玉酒初醒。","小冠子夏如相问，为道穷愁老一经。"]},{"t":"送刘宗师入觐，次虞学士韵","f":"七言律诗","c":["羽轮暂别大茅峰，又御青冥万里风。","月帔引朝宣德殿，云韶赐宴集灵宫。","悬知汉室龙颜主，似见商岩鹤发翁。","便使图形在麟阁，闲心只爱白云中。"]},{"t":"送刘年基高士还江东，兼柬张一无二首 其一","f":"七言律诗","c":["剑寒秋水客东归，堂上慈亲白发稀。","棂具定无璊玉璏，线痕犹是紫烟衣。","蜂营崖蜜花争发，鹿养春茸蕨正肥。","自古山林有甘脆，何妨物色报春晖。"]},{"t":"送刘年基高士还江东，兼柬张一无二首 其二","f":"七言律诗","c":["为问江东张道士，著书还了致桑篇？","江湖冷落番君老，云汉昭回象帝先。","芋火夜煨霜后叶，菜庖朝汲涧中泉。","相依共住知何日？","孤鹤东还意惘然。"]},{"t":"寄贞居张儒仙","f":"七言律诗","c":["露冷玄洲草木疏，砚泉分得涧循除。","钩题石记脩人表，笔削山经作志书。","丹鼎晓温松节酒，茗瓯春点菊苗菹。","残骸若有登真分，亦欲西游候羽车。"]},{"t":"简张仲举待制","f":"七言律诗","c":["宵占两两使星东，川后迎恩启閟宫。","海上天灯悬宝月，帷中神语飒冷风。","云团芝盖香烟直，春入衢尊酒味同。","况是词臣工致祝，鲸波永息岁恒丰。"]},{"t":"送钱思复之东嘉","f":"七言律诗","c":["校官东上斗城时，水落高滩舟楫迟。","造化纵凭修月斧，文章须是表忠碑。","斋庖近昼空弹铗，诗说穷源屡解颐。","来岁秋闱战仍捷，桂林折取最高枝。"]},{"t":"赠柯敬仲，次王止善韵","f":"七言律诗","c":["楚天鸿雁白云秋，归卧沧江看水流。","莫问湘累王子宿，且同新息贾胡留。","山林不返趋朝梦，道路难为筑室谋。","莫遣虹光贯明月，眠波帖下有沙鸥。"]},{"t":"喜雪寄达监司，次寿道韵二首 其一","f":"七言律诗","c":["去年南国暖如蒸，岁尽犹多扑缘蝇。","直恐蛇神司有厉，可须麟笔纪无冰。","元勋复相调金铉，稔岁恒占应玉绳。","伫听赓歌继豳雅，万年枝上日东升。"]},{"t":"喜雪寄达监司，次寿道韵二首 其二","f":"七言律诗","c":["正自风流歌白雪，何须辛苦赋青蝇？","成章雾豹方依穴，鼓枻神鱼欲上冰。","剑具寒侵璊玉璏，宫悬冻直綵绒绳。","枯鳞望活西江水，涸辙何因有斗升？"]},{"t":"钓月","f":"七言律诗","c":["籊竹裁竿拂帝青，山河影里夜亭亭。","坐乾草际沾衣露，掣得波间在罶星。","巨犗可应投贝阙，长丝便欲系天经。","清光照彻磻溪叟，方看霓裳舞广庭。"]},{"t":"梧桐月","f":"七言律诗","c":["露下秋阴洗夜光，辘轳哀响度银床。","苍龙出井献沉璧，青女抱琴弹履霜。","鹊绕暗知河汉近，凤栖明见羽毛张。","宝钗击罢宫娥老，一曲霓裳泪数行。"]},{"t":"送李秀才归越","f":"七言律诗","c":["蹑屩东归度浙河，越山无数绾青螺。","森森南国春秋学，袅袅西风子夜歌。","潮涌月轮丹桂近，山环亲舍白云多。","明年春捷灵光殿，远听鸣驺驻玉珂。"]},{"t":"赠朱君复秀士","f":"七言律诗","c":["松陵驿里雨骚骚，剪拂谁甄汗马劳？","扁石呼儿朝授简，疏棂启帙夜焚膏。","不因圣药无熊胆，每为神山有凤毛。","老我江湖读书眼，会看攀桂月轮高。"]},{"t":"送白治中之徽州","f":"七言律诗","c":["高下溪声三百滩，好山高入帝青寒。","雄藩择牧金投冶，别驾行春锦覆鞍。","茶焙香销芽尚采，砚坑云冷石仍刓。","残民久望诗书泽，阙里遗编墨未乾。"]},{"t":"挽顺义贞惠公","f":"七言律诗","c":["朔汉人豪贞惠公，策勋元自不酬功。","自从虎旅平南服，眼见龙旗捲北风。","庭有芝兰更种植，老登槐棘保初终。","只今太史修臣传，应有幽光发閟宫。"]},{"t":"次韵吴宗师题大涤洞郎师房","f":"七言律诗","c":["一庵闲地足神仙，能驻人间大小年。","赤鲩夜飞丹井月，紫鸾春步术苗田。","山经我欲紬金匮，昼漏时闻滴宝莲。","便驾飙轮上天柱，不辞身倚帝青边。"]},{"t":"寄宛丘赵祭酒","f":"七言律诗","c":["当阳圣主重师臣，妙选儒宗赞大钧。","神格西廱夔典乐，名高北斗愈垂绅。","金绳著钮编珠贝，瑶草纾花毓凤麟。","老我钓纶江海上，烟波空爱白鸥驯。"]},{"t":"题海运省官卷","f":"七言律诗","c":["省幕分贤佐上台，参模须仗出群材。","九年鹏翼乘云上，万斛龙骧破浪开。","已见清风生白简，便朝红日诣金台。","美哉王度关元化，政藉群公翊戴来。"]},{"t":"谢刘廷干漕使馈肉","f":"七言律诗","c":["琐屑鱼虾不厌腥，惊闻一脔到斋扃。","荠肠久断闻韶味，蒿目愁看在罶星。","破履尚图儿致养，解颐空对客谈经。","西风峭急江湖晚，何处充饥有楚萍？"]},{"t":"王本斋参政挽辞","f":"七言律诗","c":["甘棠港口咽寒潮，帝促明公黼衮朝。","已有旗常昭日月，却骑箕尾上云霄。","北风吸歘年华尽，南国凄凉士气销。","便欲一为天下恸，英魂不用楚词招。"]},{"t":"题钟绍京书灵飞经","f":"七言律诗","c":["匣里钟郎六甲经，虹光夜夜射天星。","使来海上持龙节，驾下云端拾凤翎。","金母度祠黄帝录，玉真按笔紫皇听。","勤修苦炼资轻举，濯足明河上九青。"]},{"t":"简金伯祥高士","f":"七言律诗","c":["瞻云西迈思悠然，过雨群峰紫翠连。","儿子劬书能继业，羽人接袂且谈玄。","可无海上安期枣，更有山头太华莲。","便驾飙轮脱尘网，劫灰不到郁蓝天。"]},{"t":"赠张月庭道士","f":"七言律诗","c":["为爱中庭月一方，坐看河汉转苍苍。","山河影在无圆缺，漏刻声中有短长。","灵药杵风金兔伏，桂花霏雪綵鸾翔。","广寒原是栖真地，歌引霓裳入醉乡。"]},{"t":"次倪元镇韵，寄刚中","f":"七言律诗","c":["缥缈陈王湖里寺，琮琤郑老竹间棋。","每因海月参心镜，却笑茶烟袅鬓丝。","墨渍尚嗔龙尾滑，酒酣方忆虎头痴。","论文未极终宵话，且让韩山一片碑。"]},{"t":"和潘子素宿倪元镇宅，送张贞居还茅山","f":"七言律诗","c":["扣舷溪子发阳阿，落叶霜林见鸟窠。","清閟阁前春意早，萧梁台上月明多。","倾瞻鸣雁嵇中散，仰视飞鸢马伏波。","对酒息思千古事，潘郎刺促为谁歌？"]},{"t":"杭州即事二首 其一","f":"曲","c":["瓦砾堆堆塞路坳，胜游巷陌尽蓬蒿。","祠宫地卧驼鸣?，秘殿春扃马矢臊。","山色无如今度惨，潮头可似昔时高？","王师贵在能安集，岂必兵行血渍刀？"]},{"t":"杭州即事二首 其二","f":"七言律诗","c":["往来都是石尤风，身境俱忘逆顺同。","镜里转增双鬓白，花前仍是小桃红。","莫惊天地军麾满，尚喜江湖客棹通。","杨柳吹绵春又暮，赋诗愁杀杜陵翁。"]},{"t":"元宵怀钱塘二首 其二","f":"七言律诗","c":["钱唐江上雪初晴，鳷鹊楼前月正明。","万炬金莲开火树，六龙翠辔降瑶京。","箫韶并入钧天奏，宫掖欢闻下土声。","犹是向来歌舞地，鬼灯寒雨暗荒城。"]},{"t":"送萧万户西归","f":"七言律诗","c":["将军旗鼓镇西州，六诏猖狂一战收。","馀墨朝犹磨楯鼻，重环夜已附刀头。","归朝却献王褒颂，去国惟存季子裘。","醉里相逢歌按剑，沧江斜日水悠悠。"]},{"t":"次韵答玉山二首 其一","f":"七言律诗","c":["扁舟不乱白鸥群，又复移家入水云。","载酒可无人问字？","挥毫故有客书裙。","荒凉汉室铜盘泪，剥落周宣石鼓文。","犹藉顾循能慰籍，江湖冷落见番君。"]},{"t":"次韵答玉山二首 其二","f":"七言律诗","c":["谁似廱侯孙子贤，宴宾歌舞斗清妍。","门前岸脚占潮讯，苇里拿音候客船。","海气若浮山隐玉，野光纯净月当川。","人生得意须行乐，莫遣闲愁到酒边。"]},{"t":"赠岑医士","f":"七言律诗","c":["经络多岐脉贯身，颠崖性命属谁伸？","如生独得岐黄秘，起死能兼郭华神。","龙献古方长系肘，虎巡熟杏不伤人。","悬知此道无疵吝，花发莺啼到处春。"]},{"t":"寄吴江知州干寿道","f":"七言律诗","c":["熙熙爱日仰高亭，亭外天寒渚柏青。","晓驾朱轓理公事，夜烧银烛校馀经。","炊烟白际鱼龙国，野稻黄铺雁鹜汀。","三载政成儒术验，玉堂亲擢暂须停。"]},{"t":"送唐学录归新安","f":"七言律诗","c":["冷落斋宫荠绕墙，归桡不待渚芹香。","新炊旋出滩边碓，弊笱仍悬涧下梁。","云气欲晴山绕屋，书声向晓月窥床。","斯文三世研磨力，破砚于今政宝藏。"]},{"t":"送任学录归松江","f":"七言律诗","c":["海边委却钓鳌竿，鼓箧来吴佐学官。","纠录尽推经术邃，藏修不厌客毡寒。","篷窗夜听蒹葭雨，荠馔朝餐苜蓿盘。","三载赋归春欲暮，柳花如雪暗江干。"]},{"t":"送毛彦昭归三衢","f":"七言律诗","c":["载雪曾过太末溪，天寒沙石净无泥。","碓舂白粲连滩响，橘坠红金压树低。","水驿灯明惊见雁，篷窗酒醒忽闻鸡。","龟峰记在君归读，异日春风听马蹄。"]},{"t":"送沈仲说游杭","f":"七言律诗","c":["钱唐湖上水西头，历历山人旧钓游。","相府犹馀秋水观，酒旗多挂夕阳楼。","春喧车马松间寺，夜载笙歌月下舟。","见说于今总消歇，休文到日重凄愁。"]},{"t":"石抹万户挽辞","f":"七言律诗","c":["提师海上戮奔鲸，玉帐宵寒陨大星。","铁马嘶风秋雨暗，天狼殷斧夜潮腥。","常时仗钺今传剑，前度平蛮未勒铭。","想见城阴练卒处，三军泪洒烧痕青。"]},{"t":"潘子素翠雨亭","f":"七言律诗","c":["竹梧亭子翠珊珊，人在空濛烟雨间。","春暮但闻莺百啭，秋阴每见鹤孤还。","且看树顶遥峰碧，莫踏苔花滴露斑。","如此林居不归去，高情谁与共萧闲？"]},{"t":"杨铁崖新居书画船亭","f":"七言律诗","c":["草玄心苦意如何，舣岸舟轻不动波。","听雨夜篷烧烛短，截云湘竹喷愁多。","赋成犹梦横江鹤，书罢应笼汎渚鹅。","想见后堂凉月白，彭宣肠断雪儿歌。"]},{"t":"张伯雨精舍吟","f":"七言律诗","c":["翩翩风流江海姿，青山满眼空遐思。","圯桥授书帝者佐，襄城问道天为师。","题扇书裙莫相恼，传符继录容何辞。","愿逐西飞白云去，沧江斜日吹参差。"]},{"t":"复见心豫章山房","f":"七言律诗","c":["豫章拔地即参天，突兀山房樟树边。","僧占绿阴开户牖，境因黄落见山川。","神机触破栽培力，佛慧看空大小年。","一自龙驹踏人后，交柯密叶正骈骈。"]},{"t":"赵子期尚书小瀛洲","f":"七言律诗","c":["粉署煌煌闪幼霞，道山宫阙宰衡家。","碧梧每集朝阳凤，瑞露长滋夜合花。","风里槐音闻奏乐，秋来星彩验乘槎。","十洲多是神仙宅，谁识溪真尚浣纱？"]},{"t":"题曹松径家谱","f":"七言律诗","c":["三径虽荒松尚存，东川遗老识清门。","秋香岁发庭前桂，霞气朝升屋角暾。","春雨丘园花结子，夜潮沟洫浪留痕。","留停户屦知多少？","但说师严道并尊。"]},{"t":"云槎","f":"七言律诗","c":["昆崙河源不易穷，灵槎万里待秋风。","载云欲问成都卜，持节知成博望功。","既犯星辰上天汉，盍为霖雨佐年丰？","如何旅泊严陵里，只挂诗囊与钓筒？"]},{"t":"次韵沈存斋见寄","f":"七言律诗","c":["八咏楼前藻思新，白鸥波上最情亲。","诗盟有喜诸君在，情话无如野老真。","历代宝归金匮钥，重山光吐器车银。","丁宁笠泽烟波上，留取珊瑚拂钓纶。"]},{"t":"送干寿道知州婺源","f":"七言律诗","c":["百滩春水不容舠，滩上春红发小桃。","龙尾磨云濡判笔，鱼须抽雪映宫袍。","神杉树密鸦啼晚，仙舍山深月出高。","使节梅花香里过，幼霞初日即岩嶅。"]},{"t":"送杨季民采诗还江西","f":"七言律诗","c":["悲凉南国采诗归，大雅寥寥入谱稀。","白马尚谁歌有容，绣裳犹自赋无衣。","离鸾顾影秋弹瑟，舞凤衔梭夜织机。","辑录已成垂世教，珊瑚枝上看朝晖。"]},{"t":"送李秀才乡举","f":"七言律诗","c":["秋风又复度宫槐，文采何人似尔佳？","月拥素娥迎学子，桂摇金果散天街。","剑光出匣惊时日，笔阵翻云写壮怀。","从此图南展鹏翼，横飞溟涬渺津涯。"]},{"t":"挽慎独陈叔方","f":"七言律诗","c":["诗书世绪传家久，金石交情举世稀。","道在人弘不远复，子依父葬表全归。","忍将完璧埋黄壤，赖有坚珉立翠微。","自恨居贫乏一祭，犹凭絮酒哭斜晖。"]},{"t":"赠张景亮仕回","f":"七言律诗","c":["投老何曾畏简书，青山元不负吾庐。","鱼须久叠床头笏，马軏新悬屋角车。","翠被春寒听雨睡，白头日午趁风梳。","好官付与诸郎做，千古封留意有馀。"]},{"t":"春游石湖","f":"七言律诗","c":["越来溪上水瀜瀜，闲蓦鸱夷棹底风。","暖雾黄消治平寺，烧痕青入馆娃宫。","笙歌作乐年年少，鱼鸟关情处处同。","吊古从来易兴感，尚循华发系孤篷。"]},{"t":"游支硎南峰","f":"七言律诗","c":["词客幽寻胜洞庭，神僧名迹在支硎。","马骑仄径犹存石，鹤放颠崖尚有亭。","岩底泉飞轻练白，峰头龛蚀古苔青。","到来顿醒红尘梦，万树松涛沸紫冥。"]},{"t":"送方养心游茅山，寄贞居外史","f":"七言律诗","c":["天上仙真骑虎还，山中宰相著书闲。","神明秘典抽金匮，早晚恩言下玉关。","风磴入云芒屩冷，松花满地术畦悭。","愿随君去携薪水，犹得栖迟涧壑间。"]},{"t":"至正三年癸未冬辜月廿六日，贞居由荆溪过林下，留旬有三日，为写云林萧散图，并赋长句书其上留别","f":"七言律诗","c":["人间契阔六年馀，清夜迎船过隐居。","寒日当阶散霜雪，疏篁绕壁韵笙竽。","烧香遂入维摩室，振席闲研老氏书。","久识先生有仙骨，莫年服食转清虚。"]},{"t":"六月六日，初度有感","f":"七言律诗","c":["三十六陂空似昔，荷花荷叶待谁看？","星辰不合躔龙尾，性命何嫌似鼠肝？","盘石处安心不转，蓼莪才说泪难乾。","晚来惟有墙头月，依旧清辉照鹖冠。"]},{"t":"嘉潘总戎征南回","f":"七言律诗","c":["万里乘轺出帝城，涉波南海斩奔鲸。","回辕不困壶中隐，乘棹来寻谷口耕。","尚可班荆谈智略，何嫌拾芥取功名？","更吹箫管扬州去，莫遣春愁白发生。"]},{"t":"送萧万户还蜀二首 其一","f":"七言律诗","c":["总戎西蜀几经年，从事谁令尔独贤？","跃马莫矜横槊赋，闻鸡不道枕戈眠。","韬藏宝剑尘生匣，爱惜雕弓夜弛弦。","归到阆州三月尽，江花如锦照行鞯。"]},{"t":"送萧万户还蜀二首 其二","f":"七言律诗","c":["百丈牵江诣阆州，旌旗拥接旧君侯。","按行貔虎千岩戍，蹴踏鱼龙万里流。","夺锦亭围花阵雨，离堆记积藓痕秋。","平生谩有相如檄，拿手何时作胜游？"]},{"t":"次倪元镇见寄","f":"七言律诗","c":["穴墙薜荔根株悬，倒架蒲萄藤蔓牵。","非无洛下先生屋，须得邛州录事钱。","鸿雁天高青不雨，鹡鸰沙晚白生烟。","松云隐屋结搆未？","何日书来解榻眠？"]},{"t":"元镇画","f":"七言律诗","c":["倪郎作画如斲冰，浊以净之而独清。","溪寒沙瘦既无滓，石剥树皴能有情。","珊瑚忽从铁网出，瑶草乃向斋房生。","譬则饮酒不求醉，政自与物无亏成。"]},{"t":"赠篆刻朱生盛","f":"七言律诗","c":["子刻印如刻秋涛，转摺变化手纵操。","螭扁神凝李斯篆，肯綮妙悟庖丁刀。","汉章旧制蟠龟钮，魏武新书閟虎韬。","太史周南纵留滞，剑文仍欲洗金膏。"]},{"t":"送达兼善秘书","f":"七言古诗","c":["木天高拱夜何其，翠被初寒更漏迟。","上帝录书藏紫禁，贵神燃火出青藜。","悬知策府稽诹处，预想虞廷献纳时。","厚报亟盈荼荠颂，湛恩心写蓼萧诗。","岂徒述作矜雄艳？","政以都人启蔽亏。","国典每濡双赐笔，宠光长发万年枝。","从容宝鼎开金镜，缥缈祥烟度玉墀。","儒术致君还有道，皇明鉴物本无私。","庙谟已发群生秘，岩穴宁令一士遗？","歌咏太平还有日，腐儒头白在茅茨。"]},{"t":"送吴平章","f":"七言古诗","c":["圣君图治思黄发，国老除书下紫宸。","身喜围腰虹玉重，眼明补衮色丝匀。","乞言应笑桓荣陋，济美谁如郑武频？","阿阁近天鸣采凤，恩波泽物到枯鳞。","锡书每启金华秘，赐馔时分玉食珍。","出处岂惟关世运？","旬宣何以布皇仁？","门人莫惜狂论事，驭吏何妨醉吐茵。","岂但勋名誇众口？","太常旗上是三辰。"]},{"t":"送林照磨之越","f":"七言古诗","c":["朱甍翼翼小蓬莱，秋水芙蓉次第开。","真宰不遗生物意，参谋须藉出群材。","风生幕府文书静，月转城楼画角催。","喝道莫惊刘宠庙，赋诗还上越王台。","鉴湖水涨陂间稻，禹穴云荒石上苔。","土有茶芽方入贡，陵无麦饭孰兴哀？","齐民恳恻知何已？","此日登临亦快哉。","日脚萧韶天姥下，潮头旗鼓孝娥来。","神人驩喜樯风顺，溪上千帆往复回。"]},{"t":"盛氏野秀堂","f":"七言古诗","c":["野秀堂前湖水绿，绕湖千嶂列檐阿。","岸花隔浦飞红雨，林木含风拥翠波。","酒醒忽持如意舞，诗成或击唾壶歌。","绝怜吹絮翻金鲫，更爱将雏睡白鹅。","邻艇卸帆绳擉布，田扉邀饮町畦过。","栽兰九畹秋纫佩，织锦全机夜度梭。","去国娉婷谁共载？","逃虚放旷自同科。","橘中尽有商岩乐，奈尔春愁鬓影何！"]},{"t":"顾氏绿阴亭","f":"七言古诗","c":["顾家亭子绿阴阴，杨柳菰蒲岸岸深。","鹭下积陂明霁雪，莺啼丛薄度镕金。","凉云覆地苔粘屐，疏雨沾衣露满襟。","境旷始知清昼寂，舟行忽见白沤沈。","锦香承宇花如雾，星采当阶月在林。","荷钁课童栽药物，开窗傍水候跫音。","湛痴元自能谈易，嵇锻何妨善鼓琴。","况是松醪酿初熟，公馀莫厌客同斟。"]},{"t":"周左丞玉雪坡","f":"七言古诗","c":["玉雪坡前一色云，更无纯白斗氤氲。","春回土脉孤亭在，山掩人家半路分。","铁石峥嵘推宗相，江湖冷落念番君。","调羹佳实花时见，喷笛清风海内闻。","墨积砚坳留凤咮，香飘池上点鹅群。","商盘久向坑灰冷，秦篆何曾野火焚？","已翼庙谟跻丙魏，兼闻户履有河汾。","腐儒独愧身如腊，已老何殊辟蠹芸？"]},{"t":"俞石涧读易处","f":"七言古诗","c":["先生注易隐南城，激石松风答涧声。","式玉式金王度在，一寒一暑岁功成。","要参未画须心悟，洞彻群疑贵理明。","蔀屋见星元是昼，寰瀛捩柁可无程。","义精讵忍辞扪舌？","乐大何妨枕曲肱。","雨露每滋庭草绿，云霞不碍晓山横。","成林讵舍千章木？","求友难忘百啭莺。","岁月推迁陈迹在，启蒙长忆酒同倾。"]},{"t":"渡江","f":"七言古诗","c":["突起金鳌玉作围，天于设险出神机。","众流不息朝宗意，元气长浮落日辉。","云叶暗吹神女佩，浪花应湿定僧衣。","鱼龙不碍中流舞，鸿雁能忘北首归？","桃叶翠颦杨子渡，麦苗青茁蒜山矶。","不因慷慨投鞭众，自是艰危击节稀。","总会华夷民阜杂，分徵玉帛使舟飞。","射蛟人去空英杰，化鹤仙来叹是非。","西日柁楼仍浩浩，南冠鬓发故依依。","书生闭户堪终老，跋涉何劳与命违。"]},{"t":"橘隐，为秦文仲赋","f":"七言古诗","c":["橘熟曾登隐者堂，傲霜林薄斓青黄。","花时吐蕊珠成斛，丛晚抽条绿閟房。","千树君封培植大，慈闱母老孝思长。","疗疴欲得苏家井，受命难迁屈子乡。","自以辟人甘濩落，谁令登俎荐芬芳？","苞缄万里深随贡，御宴群臣手擘尝。","霜落洞庭天窅窅，根盘林屋野苍苍。","斋庐并海诗吟处，雾雨氤氲著纸香。"]},{"t":"寄杨彦远隐君","f":"七言古诗","c":["子云家在让王村，昆弟三人行最尊。","胜槩不烦多屋宇，醉乡元自有乾坤。","蒙天锡福身长健，与物为春道自存。","璊玉坠枝桃结子，翠幢罗盖竹生孙。","按歌亲制萦云曲，教舞长开待月轩。","艺足稻田青雨泼，睡浓嶶帐锦香温。","不于野隐惭雌伏，政以朝趋怯骏奔。","比迹梁鸿脱尘网，追踪巢父洗心源。","佛香梵夹还投老，取次毗邪不二门。"]},{"t":"挽牟县尹","f":"七言古诗","c":["谁继清忠最老成，韦庵头白气峥嵘。","平生学术尊刘向，少日声名盖贾生。","制锦老为溪上邑，横金晚致幕中评。","高怀直欲吞馀子，爽气何堪发九京？","絮酒益兴霜露感，书题重积死生情。","羊昙恸哭青山路，宿草萋萋夕照明。"]},{"t":"送铦仲刚游金陵","f":"七言古诗","c":["铦衲来从日本东，说法亲曾授老龙。","珠树摘花抽藻思，金膏潴水淬神锋。","玄机不发空中镝，信器应传雨里舂。","暂玩一轮吴渚月，便依千尺定林松。","江光宛似玻瓈合，山色依然翠黛重。","寒水但馀鸥泛泛，荒台无复凤雍雍。","霜凋锦树存孤柏，海涌青瑶见独峰。","未识笑翁空比拟，城楼月上忽闻钟。"]},{"t":"石湖十二咏 其一 石湖","f":"五言绝句","c":["沧波渺千顷，何处觅鸱夷？","同姓千年后，流芳著断碑。"]},{"t":"石湖十二咏 其二 新郭","f":"五言绝句","c":["阖庐创城郭，俄徙傍湖山。","酒旆千家室，今犹作市寰。"]},{"t":"石湖十二咏 其三 拜郊台","f":"五言绝句","c":["吴子筑圜丘，祀帝存壝址。","鲁亦取圣讥，大禘同失礼。"]},{"t":"石湖十二咏 其四 行春桥","f":"五言绝句","c":["醉拥捧心过，韶华艳绮罗。","至今湖觜上，彩霓卧沧波。"]},{"t":"石湖十二咏 其五 越来溪","f":"五言绝句","c":["始由尝胆凿，战槛逐波通。","今日凭谁占？","渔家一笛风。"]},{"t":"石湖十二咏 其六 观音岩","f":"五言绝句","c":["碧潭通海眼，崖设大士座。","宛如访天台，石梁飞度过。"]},{"t":"石湖十二咏 其七 治平寺","f":"五言绝句","c":["云坞蕴招提，开窗面湖渚。","时发钟磬音，惊散沙鸥侣。"]},{"t":"石湖十二咏 其八 茶磨峤","f":"五言绝句","c":["孤屿突苍翠，波环郁盘盘。","谁嗜先春味？","当来制凤团。"]},{"t":"石湖十二咏 其九 楞伽塔","f":"五言绝句","c":["危峰耸浮屠，七级雕阑曲。","影落湖波心，鱼龙骇常伏。"]},{"t":"石湖十二咏 其十 越公井","f":"五言绝句","c":["隋将移城时，凿供万夫饮。","清泠寻丈馀，倒浸青天影。"]},{"t":"石湖十二咏 其十一 御书亭","f":"五言绝句","c":["敕赐宋名臣，穹碑载奎画。","至今孤亭中，虹光照山白。"]},{"t":"石湖十二咏 其十二 紫嶶村","f":"五言绝句","c":["公退紫薇省，宅种紫薇花。","千树临山麓，秋来粲晓霞。"]},{"t":"怀王敏德长者","f":"五言绝句","c":["清风起乔木，虞麓浣花庄。","老我成长望，平安字数行。"]},{"t":"怀亡友岳汉阳","f":"五言绝句","c":["白璧埋黄壤，清风忆锦袍。","何当絮酒酹？","斜日下林皋。"]},{"t":"寄张景昭二首 其一","f":"五言绝句","c":["旧宅桃花坞，流波映草堂。","睽离将二月，听雨在方床。"]},{"t":"寄张景昭二首 其二","f":"五言绝句","c":["梧竹荫萧斋，苔花绿上阶。","可堪春欲去，捉笔遣吟怀。"]},{"t":"朱泽民山水","f":"五言绝句","c":["吹箫江浦秋，舟荡碧云幽。","拟溯岩松下，诗盟订白鸥。"]},{"t":"永定空衲者送茶","f":"五言绝句","c":["尘虑困春华，蒙分谷雨芽。","醍醐滋舌本，清气溢诗家。"]},{"t":"岳生画竹","f":"五言绝句","c":["修篁含雨馀，枝拂清风起。","扫破碧玲珑，高堂净如洗。"]},{"t":"陈正孚画","f":"五言绝句","c":["冯岭少微星，群峰列帝青。","太丘亲貌得，岩壑想尝经。"]},{"t":"高彦敬画","f":"五言绝句","c":["千叠砚坳云，岩崖杳莫分。","图馀清兴在，又为客书裙。"]},{"t":"过九里寺","f":"五言绝句","c":["湖边法喜楼，千顷冷涵秋。","吟绕维摩室，风生杜若洲。"]},{"t":"李遵道新竹","f":"五言绝句","c":["逗土细行鞭，苔茵暖透穿。","生生无限意，都属蓟丘仙。"]},{"t":"陈抟像","f":"五言绝句","c":["十年营一睡，醒起欲安民。","忽睹金乌彩，还山遂老臣。"]},{"t":"云林小景","f":"五言绝句","c":["云起野桥西，层峰翠隔溪。","欲寻清閟阁，古木压檐低。"]},{"t":"王元章梅","f":"五言绝句","c":["明月西湖上，清光儗旧时。","东风露消息，香雪满南枝。"]},{"t":"子昂兰","f":"五言绝句","c":["孤臣万古愁，湘渚水东流。","江芷汀蓠满，空令泣楚囚。"]},{"t":"子固水仙","f":"五言绝句","c":["仙姿艳玉肌，轻拂五铢衣。","罗袜凌波去，香尘蹙步飞。"]},{"t":"柯敬仲竹","f":"五言绝句","c":["羁栖江梅姿，飞墨鬓如丝。","天远鸾留影，筼筜雨后枝。"]},{"t":"子庭古木","f":"五言绝句","c":["巨材千稔资，特立僵挺挺。","东风吹不回，雪崖冰壑冷。"]},{"t":"明雪窗兰","f":"五言绝句","c":["结跏向双峨，濡毫成九畹。","袭佩芳馨多，怀人江浦远。"]},{"t":"忆杭","f":"曲","c":["湖山今古妍丽，寝园此际荒凉。","春晚花开花落，故交谁在谁亡？"]},{"t":"渊明像","f":"曲","c":["弃官亟返柴桑，家资日付壶觞。","莫道先生长醉，义熙年号不忘。"]},{"t":"题画二首 其一","f":"曲","c":["六椽僦居避世，一瓢澹饮怡情。","短褐少陵已往，小冠子夏复生。"]},{"t":"题画二首 其二","f":"曲","c":["雪喷满溪泉溜，云屯匝地松阴。","隔岸芙蓉千叠，助我吟诗抚琴。"]},{"t":"怀徐士弘","f":"七言绝句","c":["钱唐湖上筱骖游，一榻长为孺子留。","头白无成两漂泊，输君天地一沙鸥。"]},{"t":"怀张天民","f":"七言绝句","c":["金坛郭里扫尘斋，移向宜兴傍古槐。","孙子读书儿致养，更无尘杂到苔阶。"]},{"t":"张贞居神光楼看雨三首 其一","f":"七言绝句","c":["东风吹雨弄新晴，仙子楼居吹玉笙。","不是春阴在帘幕，已应颠倒落红英。"]},{"t":"张贞居神光楼看雨三首 其二","f":"七言绝句","c":["濛濛灵雨向东来，曙色轩窗面面开。","为爱条风吹润绿，莫教人迹印苍苔。"]},{"t":"张贞居神光楼看雨三首 其三","f":"七言绝句","c":["碧云千仞紫阳山，都在东风化雨间。","细与阳春同霢霂，岸花汀柳亦斑斑。"]},{"t":"赠制笔温生二首，并引 其一","f":"七言绝句","c":["神光楼上春联句，醉里纵横笔屡挥。","归到吴中见蒙子，斯文徵艺有神机。"]},{"t":"赠制笔温生二首，并引 其二","f":"七言绝句","c":["温生有子能传业，郑老无书可寄君。","他日制成壸领记，尚凭毛颖话慇勤。"]},{"t":"病中寄王叔明","f":"七言绝句","c":["跌宕王郎天马驹，胸蟠百箧外家书。","雨窗卧病三十日，裹饭何曾见子舆？"]},{"t":"陶靖节像","f":"七言绝句","c":["袖里惭无博浪槌，酒醒空赋稚桑诗。","悲凉一曲山阳笛，满眼山河是义熙。"]},{"t":"谢太傅像","f":"七言绝句","c":["秦兵百万压东南，宗社安危已独担。","却置捷书棋局底，诸君犹认罪清谭。"]},{"t":"病中寄光孝禅翁","f":"七言绝句","c":["我病在床身欲飞，棋锋何日赌神机？","想应近日翻经后，只有青山到竹扉。"]},{"t":"题画六首 其一","f":"七言绝句","c":["舒啸风林云满溪，白驹空谷草萋萋。","相逢不作苏门听，应有长松鹤未栖。"]},{"t":"题画六首 其二","f":"七言绝句","c":["濯足清溪水已寒，青山犹有此衣冠。","黄尘三尺乌靴底，谁与归来把钓竿？"]},{"t":"题画六首 其三","f":"七言绝句","c":["水缭山回深复深，白云茅屋住溪阴。","溪南十亩堪耕种，何必囊中季子金？"]},{"t":"题画六首 其四","f":"七言绝句","c":["桂树连蜷山石幽，萧然冠屦白云秋。","只愁畏垒无尸祝，不愧长年为尔留。"]},{"t":"题画六首 其五","f":"七言绝句","c":["桃花源上蝶飞飞，误却渔郎苦欲归。","云白山青一回首，落红如雨点春衣。"]},{"t":"题画六首 其六","f":"七言绝句","c":["仙人楼观隔层霞，隐者烟萝便作家。","万壑千岩何处是？","停桡试问碧桃花。"]},{"t":"肥、瘦二马 其一","f":"七言绝句","c":["狮子花骄蹴暖风，满臕如瓠气如虹。","年来恣饱天闲粟，朔漠当收血战功。"]},{"t":"肥、瘦二马 其二","f":"七言绝句","c":["百战才馀骨与毛，枯株倚着费抓搔。","何人终惠还刍秣？","拂拭风鬉气尚豪。"]},{"t":"丛竹图","f":"七言绝句","c":["赋诗何处极幽探，多在青山海岳庵。","一片绿云尘迹断，万竿烟雨大江南。"]},{"t":"游鱼图","f":"七言绝句","c":["泼剌春波藻荇深，方池容得五湖心。","砚坳更有神龙在，难邈商岩旱岁霖。"]},{"t":"题文山佩刀帖","f":"七言绝句","c":["径露刀金柄属谁，空闻断指血淋漓。","杜鹃啼暗江南月，臣甫年年泪雨垂。"]},{"t":"子昂临东坡竹","f":"七言绝句","c":["戏墨王孙似子瞻，鸡栖石上着毵毵。","汴京回首西风急，流落江南共海南。"]},{"t":"东坡笠屐图","f":"七言绝句","c":["得嗔如屋谤如山，且看蛮烟瘴雨间。","白月遭蟆蚀不尽，清光依旧满人寰。"]},{"t":"伏生授经图","f":"七言绝句","c":["老无牙齿语音讹，断简残编缺字多。","不赖闺中贤弱息，帝王典则竟消磨。"]},{"t":"苏武牧羊图","f":"七言绝句","c":["飞鸿历历度天山，何处孤云是汉关？","不滴望思台下血，君王犹及见生还。"]},{"t":"岳王庙","f":"七言绝句","c":["复得中原后杀身，将军未必恨奸秦。","甘将三百年宗社，君相偷安葬塞尘。"]},{"t":"武侯像","f":"七言绝句","c":["鱼水君臣百世师，风云鱼鸟识旌旗。","三分天下何经意？","恨未中原复本支。"]},{"t":"读碑图","f":"七言绝句","c":["摩挲汉鼎朵馋颐，臣道为忠孝可移。","枉使南来五千里，越江漫读孝娥碑。"]},{"t":"月夜怀十五友，并引 其一 赵宛丘","f":"七言绝句","c":["剡剡台躔映五云，通明殿上玉宸君。","今宵赏月延秋桂，满袖天香不见分。"]},{"t":"月夜怀十五友，并引 其二 张贞居","f":"七言绝句","c":["月华浮海绿烟收，曾照神光湖上楼。","惆怅尘生白玉麈，诗盟从此负闲鸥。"]},{"t":"月夜怀十五友，并引 其三 李云中","f":"七言绝句","c":["屋角冰盘拥烂银，清光千里不疏亲。","弃官归去轻如叶，应念沧江有钓纶。"]},{"t":"月夜怀十五友，并引 其四 倪云林","f":"七言绝句","c":["览古楼高桂影寒，飞觞不厌接清欢。","天香落尽黄金粟，软语何由接夜阑？"]},{"t":"月夜怀十五友，并引 其五 张文德","f":"七言绝句","c":["每念道人张一无，京尘填眼髑髅枯。","师资贼害无人理，负子清光白玉壶。"]},{"t":"月夜怀十五友，并引 其六 刘张掖","f":"七言绝句","c":["汳水秋风吹雁声，一时分省有更生。","登高吊古中秋近，盖有危言答圣明。"]},{"t":"月夜怀十五友，并引 其七 泰白野","f":"七言绝句","c":["天章阁下月孤明，仍是中秋此夜情。","便到蓬莱宫里住，谢安元自念苍生。"]},{"t":"月夜怀十五友，并引 其八 草堂、宾主","f":"七言绝句","c":["芝云如盖拥冰盘，携得王珣午夜看。","山色湖光秋十里，诗成应更刻琅玕。"]},{"t":"月夜怀十五友，并引 其九 陈敬初兄弟","f":"七言绝句","c":["阖闾城里寄闲身，四壁秋蛩语近人。","何异京华旧时月？","清光且照白头亲。"]},{"t":"月夜怀十五友，并引 其十 黄金华","f":"七言绝句","c":["月上溪头树影长，婆娑老子据胡床。","九天风露归来后，桑落园林酒正香。"]},{"t":"月夜怀十五友，并引 其十一 王季野、钱伯行","f":"七言绝句","c":["飞云楼上月华明，几度中秋在帝京？","却有钱郎挥翰手，倚阑横笛最含情。"]},{"t":"月夜怀十五友，并引 其十二 张京兆","f":"七言绝句","c":["南来看月异常年，身在仙岩溪水边。","名简帝心归想近，清歌莫惜杖头钱。"]},{"t":"送张贡士","f":"七言绝句","c":["睢阳世绪邈如云，君独胸蟠锦绣文。","莫为书裙散香墨，好摅三策表奇勋。"]},{"t":"送处州杜同知三首 其一","f":"七言绝句","c":["见说吾家光禄坟，长松万个入青云。","子孙为庶杭头住，应立车尘候使君。"]},{"t":"送处州杜同知三首 其二","f":"七言绝句","c":["含辉天上少微星，曾照苍苍古括城。","山水高深民俗险，不忘辛苦事岩耕。"]},{"t":"送处州杜同知三首 其三","f":"七言绝句","c":["谁如别驾杜侯贤，纯吏心肠铁石坚。","山坂高低时雨足，郡斋篝火看畬田。"]},{"t":"赠丽水治农少府二首 其一","f":"七言绝句","c":["一寸山坳一寸田，高低岩溜接山泉。","论升起税斤称谷，此是山城大有年。"]},{"t":"赠丽水治农少府二首 其二","f":"七言绝句","c":["牛羊日夕下山时，出穴耽耽虎正饥。","不是仁侯护羸畜，麒麟折角獍枭肥。"]},{"t":"寄颜元卿院判二首 其一","f":"七言绝句","c":["户外梅花落峭寒，窗前银烛剪更阑。","贾生只为忧明主，华发萧萧镜里看。"]},{"t":"寄颜元卿院判二首 其二","f":"七言绝句","c":["年华汨汨可相饶，鱼跃春冰逆上潮。","畎亩怀君不忘处，汲生难远武皇朝。"]},{"t":"寄王可矩宗伯二首 其一","f":"七言绝句","c":["江上羊裘把钓翁，一竿烟雨致时雍。","客星祠下山千尺，不在云台彩画中。"]},{"t":"寄王可矩宗伯二首 其二","f":"七言绝句","c":["昔年簪笔上瀛洲，万里青云映黑头。","相业要知霜后柏，烝徒有楫济川舟。"]},{"t":"寄沈存斋","f":"七言绝句","c":["终惠长歌瘦马行，杜陵头白泪纵横。","风云满地无春草，顷刻难忘向主鸣。"]},{"t":"寄倪云林","f":"七言绝句","c":["经锄斋外月娟娟，尝照梅花纸帐眠。","回首三年几圆缺？","尘埃堆垛白云篇。"]},{"t":"刘功父汉川亭","f":"七言绝句","c":["玉峰深隐汉川君，安稳书巢卧白云。","天禄校书儿辈在，青山留为客书裙。"]},{"t":"虞学士小像，为其侄孙堪题二首 其一","f":"七言绝句","c":["光岳英灵盖世雄，九天象纬贯心胸。","六经文字关时运，韩柳孙丁又及公。"]},{"t":"虞学士小像，为其侄孙堪题二首 其二","f":"七言绝句","c":["紫芝眉宇凤麟姿，自是文章百世师。","何必凌烟画冠剑？","云仍翼翼奉烝祠。"]},{"t":"郭天锡云山","f":"七言绝句","c":["飞墨来从海岳庵，春风吹雨满江南。","青山肯被云遮尽，时耸尖奇一两簪。"]},{"t":"朱泽民山水","f":"七言绝句","c":["楼观参差山涧坳，渔舟远啸出林梢。","白云度尽千峰碧，鬻石幽人始定交。"]},{"t":"次泰监司提兵东广，留别吴中诸友韵二首 其一","f":"七言绝句","c":["万里南征瘴岭过，夜闻何处竹枝歌？","貂蝉原自兜鍪出，盍斩鲸鲵靖海波？"]},{"t":"次泰监司提兵东广，留别吴中诸友韵二首 其二","f":"七言绝句","c":["白发萧萧尚草元，故人江海慰衰年。","功成伫俟归来日，只在城南尺五天。"]},{"t":"寄宇文国相","f":"七言绝句","c":["精思亭上李文饶，且袖经纶镇海潮。","相业从容龙尾道，唐家复数中兴朝。"]},{"t":"寄贡泰甫授经二首 其一","f":"七言绝句","c":["姑苏台下雨声寒，舍馆青灯语夜闲。","父子日为师友处，遗经不厌静中看。"]},{"t":"寄贡泰甫授经二首 其二","f":"七言绝句","c":["风风雨雨百花洲，何日春晴一醉游？","满日青山吟藉草，鸱夷未许独扁舟。"]},{"t":"送陈玄礼之杭二首 其一","f":"七言绝句","c":["钱唐湖上雁声秋，凉入明公紫绮裘。","庾信清贫何逊老，登临难写古人愁。"]},{"t":"送陈玄礼之杭二首 其二","f":"七言绝句","c":["青山绕郭候潮过，今古兴怀意绪多。","到夜令人尚无寐，弯弯月子竹枝歌。"]},{"t":"送何举人北上二首 其一","f":"七言绝句","c":["练川文学旧从游，户屦儒生学最优。","北上神京当六月，凉风桂子已含秋。"]},{"t":"送何举人北上二首 其二","f":"七言绝句","c":["闻说京师喜气多，万家齐唱董逃歌。","坞金何日宽民赋？","海宇频频望泰和。"]},{"t":"送僧还开先","f":"七言绝句","c":["庐山面目翠千层，飞屩孤禅不厌登。","绝顶倚云无脚力，潭珠三伏洒寒冰。"]},{"t":"赠曹相士","f":"七言绝句","c":["魏武子孙谁尚贤，相人唐举得真传。","王侯蝼蚁知同尽，留取双瞳鉴碧天。"]},{"t":"陆仲明居笠泽，以卜养亲，裕如也，诗以赠之二首 其一","f":"七言绝句","c":["韩墅桥边陆抗家，灼龟灵应足生涯。","行人握粟遥相顾，虔奉慈亲度岁华。"]},{"t":"陆仲明居笠泽，以卜养亲，裕如也，诗以赠之二首 其二","f":"七言绝句","c":["事亲能孝祗天知，母子团圞不皱眉。","卖卜得钱勤孝养，菜羹香里及时炊。"]},{"t":"顾定之竹二首 其一","f":"七言绝句","c":["虎头孙子顾参军，八法纵衡写墨君。","龙伯由来宝湖石，凤毛何事刷春云？"]},{"t":"顾定之竹二首 其二","f":"七言绝句","c":["石屋老人画竹石，后之学者森如织。","河源一分百派殊，天下纷纷竟谁识？"]},{"t":"王元章梅","f":"七言绝句","c":["孤山无复看梅花，寂寞咸平处士家。","留得王髯醉时笔，岁寒仍旧发枯槎。"]},{"t":"虞胜伯画雨竹","f":"七言绝句","c":["渭川烟雨绿漪漪，公子飞云出砚池。","万个青琅秋一抹，高梢特耸凤凰枝。"]},{"t":"馆娃宫图","f":"七言绝句","c":["复殿回廊绕翠岑，鸳鸯娇拥画屏金。","谩誇歌舞留君醉，千古人犹怨捧心。"]},{"t":"揩痒马图","f":"七言绝句","c":["啄疮乌去未斜阳，雨足春堤草正长。","摩擦树根休技痒，明朝要尔战沙场。"]},{"t":"碧梧翠竹堂","f":"曲","c":["顾仲瑛父，作堂溪浒。","矗矗其楹，植植其础。","飞甍斯郁，高栱其楚。","绮疏迎阳，粉扉作堵。","文艺之苑，图书之府。","爰植梧竹，翠碧之溥。","竹益冬荣，梧因夏膴。","既敷其荫，又啸而舞。","春暮首夏，炎日当午。","合梧与竹，繁阴在下。","鱼跳矜肥，鹦啭命侣。","父既乐只，坎坎其鼓。","载陡清泉，载陈列俎。","歌声在节，丝声合拊。","竹梧交枝，高出云雨。","宾既醉止，举觞寿父。","愿父寿乐，以续妣祖。","以长孙子，以养父母，以承天之祜。"]},{"t":"春晖，美华孝子也","f":"曲","c":["阳春有晖，物其是依。","何独寸草？","春阳载辉。","菲菲芳草，沐沐春阳。","德泽之漙，寸草之长。","子之于母，其恩莫大。","鞠育成人，恩等覆载。","儿之出矣，念儿衣单。","为缝为纫，惟恐或寒。","是意之微，孰为识者？","有唐诗人，孟氏东野。","华彦清父，奉其母仪。","春草名轩，本乎孟诗。","嗟彦清父，嘅亲早寡。","奉母斯轩，饮酒伐鼓。","有孙在膝，有孙授室。","儿在母前，诸孙林立。","母喜谓儿，尔父殁时。","天高地厚，茕茕孤嫠。","安知今日，孙又抱子？","是皆尔父，积庆有此。","儿闻母言，悲喜盈襟。","歌我声诗，以慰母心。"]},{"t":"题顾宏中画韩熙载夜宴图","f":"五言律诗","c":["熙载真名士，风流追谢安。","每留宾客饮，歌舞杂相欢。","却有丹青士，灯前密细看。","谁知筵上景？","明日到金銮。"]},{"t":"题司马温公史草","f":"五言古诗","c":["典午渡江后，盗臣接迹起。","由其创业初，所事不以理。","温公成通鉴，善恶悉就纪。","心画既严正，形见在藁纸。","藁盖人所忽，敬慎不少弛。","固宜公之心，天地同终始。"]},{"t":"宿通玄观","f":"五言古诗","c":["褰衣度松声，泉石泫斜照。","采薇入山阿，白云起岩徼。","仙人驾青牛，泠然下虚峭。","璚璈鼓春风，空歌发微妙。","擘麟伤玉醴，服之五情疗。","前林忽瞑色，海月涌圆峤。","天高帝清寒，万里入遐眺。","嵯峨玄通阙，磴道归萝茑。","孙登劳我思，木末戛长啸。"]},{"t":"至正十年正月一日，与龙门僧良琦、临海陈基联句，送匡庐道士于彦成归越，兼柬萧元泰、卢益修云","f":"五言古诗","c":["岁朝逢王春，雨雪暗吴下。","行人明当发，别袂惨莫把。","飘飖贺监舟，蹀躞灵运马。","山驿梅始繁，溪船浪仍打。","行纾庄舄吟，去结远公社。","禹穴紬奥编，兰亭集群雅。","神韵鹤氅朗，风标鹅经写。","双凫继遐躅，千秋祝纯嘏。","信凭回潮尾，春融枯樟胯。","越台瞰蓬瀛，胥涛驾龛赭。","白战隐鞍甲，绿醑酣觲斝。","智囊倒精悍，词锋发侈哆。","萧史德符欤，卢敖天游者。","道枢混溟涬，语阱脱謑髁。","但令冠峨峨，肯羡绶若若？","沧海等稊米，黄金真土苴。","接罹或露发，短褐不掩踝。","捷若矢离弦，勇如金跃冶。","青云步伊始，白雪和殊寡。","土膏动勾芒，春情满原野。","桂树歌讵已？","柳枝折难舍。","别梦梁月堕，清谈松风洒。","蓬藋既可居，芦菔自堪鲊。","望望玉山阿，来朝卜灯灺。"]},{"t":"神光楼，与张伯雨联句","f":"五言古诗","c":["藏书地肺穴，归巢湖领山。","秋清蒹葭露，水落芙容湾。","虫飞烛见跋，鹤唳棚上擐。","桂丛岂充隐？","草间斯投闲。","脱帻鬓俱秃，哦诗意殊悭。","惊飙搅坠叶，疏棂袅丛蕳。","炉温夕熏罢，汀寒夜舟还。","瀛屿倚突兀，海图挂斓斑。","熊经谅方煦，豹隐知难攀？","遥闻城门柝，却换刀头环。","濡毫沥蟾滴，拄颊挥鱼颁。","倚墙童齁熟，覆杯酒肠孱。","神光出葭菼，澄怀斩茅菅。","气存验当宁，道充甘抱关。","腥腐孰不死？","伐洗我独顽。","仙从琴心舞，圣视鼎胙攽。","出处匪异致，躁静难同班。","渊宅鉴鼌气，天游涤神奸。","缅昔郿坞筑，馀此巾柙殷。","并乏麦饭飨，益重黎氓瘝。","两弹闻鹃血，重洒化鹤潸。","穷阖劫灰聚？","故国亡诗删。","于焉遁葛井，岂徒慕商颜？","茹芝腹能实，饮菊姿逾娴。","披云陟砢硪，临池漱潺湲。","神鲤破网出，乳狸据裀跧。","烟际挐画鹢，掌中喂白鹇。","去乡吴音鲠，支颐越吟艰。","一世更聚散，多岐重忧患。","睽违隔风雨，空闻佩珊瑚。"]},{"t":"同郑基本初访吴庠郑元祐明德教授、俞鼎叔铉学正，教授留饮斋中。是夕雪，因相与联句以纪一时会盍","f":"五言古诗","c":["中吴泮宫古，广文官舍敞。","佩衿方休诵，冠带骈憩鞅。","岁晏云四合，雪暮霰交响。","飞帘势簸扬，滕六影下上。","污邪毕洁净，坱轧周涤荡。","若将混端倪，无复别封壤。","飒沓竹末俯，碎兀木本强。","漏壶咽铜龙，城柝卧素蟒。","冰澌静胶研，颢气深刺幌。","香乾芸散帙，味永齑冻盎。","拥褐肩独耸，击钵技自痒。","诗盟得寒郊，茗饮失粗党。","路迷梁园邈，地失程门丈。","殊怜局驴背，颇快衣鹤氅。","沈廖度郢曲，浩溔泛剡桨。","流风注存心，叔世入纡想。","戍遥皲瘃苦，野旷爪牙攘。","好音怀鸱枭，怪物绝魍魉。","愿追文正躅，不辞庆历党。","层甍庋诸经，直道扩群枉。","新知春兰蔼，旧游曙星朗。","谦虚侧皋比，欲寡贱熊掌。","张灯初筵秩，举爵朋酒飨。","黄羞登俎柑，白荐作羹鲞。","叙齿先一饭，探钱罄馀帑。","清宜禅僧分，瑞许贤守赏。","螟蝝殄无类，来牟熟有象。","阴褰天光发，阳复履道长。","高视吞八九，独立配参两。","幸敦君子交，再极尼丘仰。"]},{"t":"月氏王头饮器歌","f":"七言古诗","c":["穹庐野布诺水东，大旗之下单于宫。","甲光五色马如蚁，列屋层毡嘶朔风。","月氏降王昔授首，圆颅启封出盛酒。","金屑露刀□□□，挠以留犁不停手。","汉国使者歃血盟，大邦气与虹霓争。","当时老上天骄子，控弦西射金天精。","数级论功溅腥血，剑花交簇阴山雪。","饮至龙廷醉蹋舞，一卮倒注阳灵穴。","哀王之殁同智瑶，帝阍盍遣巫阳招？","魂招不来守之泣，恨结玄云贯寒日。"]},{"t":"送林彦清归永嘉","f":"七言古诗","c":["玉晨明皇大道君，丹霞上宫校琼文。","芙蓉制冠珠织裙，并乘绿舆驾飞云。","有美一人岸青帉，来从东瓯东海濆。","不笑不语寡戚忻，帝惊顾语仙圣群。","是能执持神化蕴，子昔梦噩帝怒贲。","拯子于危释忧慬，报崇仙阶秩孔殷。","尚念无以章殊勋，琳宫紫幄珠流熉。","灵来乘纯去乘雯，影响浊世那由闻？","神孙飘翩接芳芬，烹阳冶阴调夕昕。","气神元精驻不分，由能鍊之久益贲。","水浸不溺火不焚，是谓真人非外棼。","雁荡木落溪沄沄，子今东归似惊麇。","将与浮脆同氤氲，酾之清泠濯垢氛。","我将学之意则勤，其如衰年日已曛。","况复岁晏手足皲，作诗送子空云云。"]},{"t":"题冯子振居庸赋","f":"七言古诗","c":["冯翁耽耽老墨虎，啸风词林彍飞弩。","熊罴象犀在不数，血人牙牙齿踰斧。","有一婴之折汝股，横行妥尾孰敢侮？","天门九关列翁伍，让翁先登翁孔武。","丙班文章耀策府，葩华綷错杂织组。","不于其彝于其阻，物不虎伤虎物遹。","枝撑倒颠人汝苦，北登居庸豁心腑。","飞峦去天仅尺五，黛拥岚浮动百堵。","翠华北巡六飞举，从官车骑多如雨。","翁如扬雄不罗缕，作赋铺陈传下土。","如何大将建旗鼓，六师如云一掷赌。","翁今骑箕还帝所，独遗手书作媚妩。","得之者谁邓春父，菖蒲为菹范登俎。","蜇喉戟唇不敢吐，还如天霜贷宿莽。","物以多贵等束楚，爨妇炀灶喜欲舞。","遂昌山樵手独拊，题诗愧无一字补，翁名星垂万万古。"]},{"t":"题钱舜举浮玉山居图二首 其一","f":"七言古诗","c":["馀不之水浮玉山，仙人来往乎其闲。","圭璋藻思发天巧，粉墨绢楮留人间。","钱翁山居窈绵密，深润山林閟白日。","翁去而今能几年？","旧游一变成荒烟。","惟有墨迹长不泯，夜夜白虹光满天。"]},{"t":"题钱舜举浮玉山居图二首 其二","f":"七言古诗","c":["客常笑我不买山，我爱水竹村幽闲。","石梁平坦行可度，吠犬鸣鸡邻舍间。","昔人养性藏深密，懒出户庭消永日。","花开花落罔知年，补屋牵动苍萝烟。","钱公画图好山树，一绿交映如春天。"]},{"t":"次韵陈子言","f":"七言律诗","c":["花蕊迎春红渐肥，烧痕伤旱绿全稀。","涸陂未下双黄鹄，空谷何嫌一布衣？","仙掌玉腴甘露降，斋房芝嫩采云飞。","德星会向良宵聚，只恐山人取醉归。"]},{"t":"催花雨","f":"七言律诗","c":["陌头微雨细皑皑，陌上小桃红未开。","尽日已催梅破萼，向阳还迫草抽荄。","长镵早与栽黄独，深巷时须步绿苔。","只恐晴明花发尽，须教梁燕早归来。"]},{"t":"生香亭","f":"七言律诗","c":["方看幽草动区萌，便有交枝啭谷莺。","树影齐圆日停午，蜂衙欲罢雨初晴。","青摹屋角山容出，翠养墙根石发生。","自为新来作诗瘦，隐侯元不负闲情。"]},{"t":"陈栖山","f":"七言律诗","c":["栖遁青山深复深，尚尔跫然闻足音。","鸡鸣树颠客叩户，水流花开风满林。","身拜东皇抚玉珥，首峨南冠弹素琴。","一闻招隐淮南赋，便将飞屩度千岑。"]},{"t":"寄李大本，兼柬理江阴","f":"七言律诗","c":["不见李丹名父子，澄江日日水烟中。","角声古戍凄霜月，暝色孤帆乱渚鸿。","苜蓿阑干朝采上，蒹葭零落岁华空。","登高能赋陪熊轼，却是穷吟倚北风。"]},{"t":"钱氏东楼","f":"七言律诗","c":["飞楼百尺堠山西，长日看山不下梯。","檐树午晴乌鸟噪，井梧月上凤凰栖。","翠娥度曲繁声换，缃帙垂签细字题。","何处一声樵子笛？","阴阴桃李绿成蹊。"]},{"t":"答谢白马奭公送茶","f":"七言律诗","c":["玉川破屋柴门晚，遣送灵苗似谷芽。","秀句惊看红药嫩，狂歌起舞白题斜。","篮封外裹藏丹箬，鼎候旁存伏火砂。","啜罢东风欲仙去，更从何处觅三车？"]},{"t":"送僧礼五台","f":"七言律诗","c":["飞锡晓辞师子林，五台天远谷岩深。","宝光面面金银刹，天乐时时钟磬音。","崖土亦知成佛贵，峡泉似泻祝尧心。","北归且向皇都住，莫听西风月夜砧。"]},{"t":"金粟影","f":"七言律诗","c":["岩桂花开江浦流，辟疆园里旧曾游。","天方雨粟成金色，风直吹香上玉楼。","空里宝云狮子座，镜中丝鬓鹔鹴裘。","姮娥手种谁攀得？","一曲鸾笙万壑秋。"]},{"t":"湖光山色楼","f":"七言律诗","c":["晴峰抹出海虞山，宛在空明野水间。","范蠡不骑丹凤去，仲雍仍驾彩云还。","浪花光闪芝三秀，雾雨寒增豹一斑。","试问风帆去何许？","想闻环佩玉珊珊。"]},{"t":"题张氏世寿堂","f":"七言律诗","c":["奕奕金坛世寿堂，钟才应运适相当。","练川新借光华月，吴县阴垂蔽芾棠。","孝友已堪民表率，清廉更作吏堤防。","殷勤父老求篇咏，写向奎仙品藻傍。"]},{"t":"翻经，奉简天民有道先生","f":"七言律诗","c":["矫矫金坛八十翁，翻经收得大乘功。","瞳人水剪琉璃碧，舌相香喷菡萏红。","一邑弦歌蒙子化，四窗灯火与孙同。","太平有日归阳羡，还理田园乐岁丰。"]},{"t":"成广陵先生以诗寄张先生，韵度深稳，谨依韵奉和","f":"七言律诗","c":["白骨自应无葬地，青山可复有遗民？","何时得返屠羊肆？","古庙无惭刺虎人。","制锦邑中推令子，听经池上跃修鳞。","绿云洞里遗编在，循省加工莫厌频。"]},{"t":"题林屋佳城图","f":"七言律诗","c":["墟陇依依隔洞庭，孝思图里柏杉青。","水烟空阔惊身在，霜露焄蒿每泪零。","林屋洞深云气重，娄江潮落雨蓬腥。","想应橘熟秋林晚，归垦岩田老一经。"]},{"t":"题管夫人悬崖朱竹","f":"七言律诗","c":["亦是檀栾池上枝，却缘朱色借胭脂。","清荫忽讶繁红藉，劲节难从染绛移。","结实定为朱凤食，腾空堪作赤龙骑。","多应血泪湘妃尽，客赋梁园总未知。"]},{"t":"物故卢氏母周夫人挽歌辞","f":"七言律诗","c":["贤哉此媪相良人，所至俱称德化醇。","妇道雍雍银鹿备，母仪抑抑彩衣新。","避兵远忆重城路，同穴全归百岁身。","日暮青山水呜咽，诸孤哀恸彻秋旻。"]},{"t":"甲子新岁","f":"七言律诗","c":["上元甲子天开日，泰定更新诏下时。","亲舍晚依吴子国，客窗山近偃王祠。","墙阴夙草春泥湿，屋角鸣禽晓日迟。","西堠梅华政如雪，晚来横笛为谁吹？"]},{"t":"次韵蒋春卿见寄","f":"七言律诗","c":["华发垂垂到鬓髾，青春故故把人抛。","生同失木狙分芋，不及知风鹊有巢。","楚泽生涯千树橘，杜陵破屋几重茅？","此时归老南山下，不梦朱干舞玉梢。"]},{"t":"扬州，寄严治中裕之","f":"七言律诗","c":["芜城孤起暮云中，边燧漂沈楼橹空。","鬼燐不销忠义血，史臣谁著简书功？","铜盐利聚吴王国，歌舞香残炀帝宫。","惟有红楼旧时月，朱帘随处卷春风。"]},{"t":"和徐生芾元宵有感","f":"七言律诗","c":["钱王宫阙暮烟平，陆海金莲此夜明。","潮去潮来沦霸业，花开花落故陪京。","九天歌舞销尘劫，万井轮蹄捲市声。","今日桓伊江上笛，卧吹落月下空城。"]},{"t":"西清庵冬日桂华盛开","f":"七言律诗","c":["桂丛何自舞传葩，惊怪玄冬见此花。","月窟再开金粟影，天香重降玉皇家。","攀枝楚客歌招隐，耐冷嫦娥起散花。","况有清霜辟蟫蠹，从兹不老是生涯。"]},{"t":"寿乐亭","f":"七言律诗","c":["西隐西边寿乐亭，六时天乐语檐铃。","傍人驯鹤行穿竹，掠水飞鱼出听经。","月到中庭开碧落，星从南极上沧溟。","千年一息那伽定，长结慈云拥帝青。"]},{"t":"题吴镇夏山欲雨图","f":"七言律诗","c":["为爱刘郎梅雪斋，纤埃不动始澄怀。","向阳蕊绽春当户，入夜寒凝晓覆阶。","梦里梨云甘落寞，腊前柳絮孰安排？","欲知千古清刚意，更向山颠与水涯。"]},{"t":"舟中望邓尉山","f":"七言律诗","c":["卧枕船舷诗思清，望中浑恐是蓬瀛。","桥横水木已秋色，寺倚云峰更晚晴。","翠羽湿飞如见避，红香染袅似相迎。","依稀似近诛茅屋，鸡犬林萝隐隐声。"]},{"t":"魏公祠","f":"七言律诗","c":["天平寺里魏公祠，翼翼蒸尝奠荐时。","庙享百年亡国后，道求千古圣人知。","山侵鸟道盘风磴，石拔鲸牙插羽旗。","更上高亭望吴下，墓田秋实正离离。"]},{"t":"寄赠华阳洞隐者","f":"七言律诗","c":["一自玄洲守法庐，研泉分得涧循除。","钓头石记修人表，笔削山经作志书。","丹灶晚温松节酒，茶瓯春点鞠苗菹。","残骸若有登真分，亦欲西游候羽车。"]},{"t":"送张仲贤北上","f":"七言古诗","c":["海上人家亦壮哉，远潮平处是蓬莱。","道人宫阙天晴见，龙伯衣冠雾里来。","东日欲升长照槛，北辰在望每登台。","凤麟洲近天光密，鳷鹊楼高雪雾开。","论治儒臣工献纳，当阳圣主急贤才。","贡琛还见柑登俎，宴席仍闻乐奏陔。","过雨绿芜连地远，翻阶红药倚云栽。","故人若问沧江老，为语穷愁绝可哀。"]},{"t":"题达监司所藏柯博士秋山图","f":"七言古诗","c":["风光南国典签孙，笔底江山妙吐吞。","云涌坐隅岩木动，瀑飞书屋浪花翻。","危桥仅尺疑虹饮，怪石逾拳作兽蹲。","可即田庐朝挂笏，只应萝月夜窥门。","林深曷致巢松鹤？","谷响如闻啸树猿。","裹饭趁墟身欲往，担簦陟峤手堪扪。","公廷未竟东方谑，画史恒推北苑尊。","老矣玉文堂上客，悲歌一恸为招魂。"]},{"t":"西马图","f":"七言绝句","c":["西来万里气如云，便策天闲第一勋。","此日登歌荐清庙，于今能得几人闻？"]},{"t":"题二马图二首 其一","f":"七言绝句","c":["奚官浴马试与骑，一匹受鞍一匹嘶。","房星之精四飞去，昭陵风雨夜凄凄。"]},{"t":"题二马图二首 其二","f":"七言绝句","c":["沙陀义儿御两马，正从梁晋争天下。","惜哉不见夹寨破，杨五功名竟独跨。"]},{"t":"题许道宁溪山秋晚图","f":"七言绝句","c":["江山黄落楚云寒，野老岩栖一坞宽。","卖药长安不求识，如何飞墨下云端？"]},{"t":"题卢益修白描水仙花","f":"七言绝句","c":["卢生吮笔写三香，海上仙人欲取将。","宫阙凝酥春雪霁，好留屏曲写孤芳。"]},{"t":"题盘松扇头","f":"七言绝句","c":["曾障西风庾亮尘，支撑根底妙轮囷。","屈将千丈虬龙质，一握生绡敢望伸。"]},{"t":"题画山水二首 其一","f":"七言绝句","c":["海岳庵前万顷云，高深显晦属谁分？","不因此老淋漓墨，那得溪山在练裙？"]},{"t":"题画山水二首 其二","f":"七言绝句","c":["画史谁如此老颠，能融笔墨写山川。","青林白石江南路，何处堪耕二顷田？"]},{"t":"题梅花卷","f":"七言绝句","c":["此花政如黄叔度，不见令人鄙吝生。","谷底岁寒谁邀得？","白驹欹侧晚烟明。"]},{"t":"题柯敬仲墨竹","f":"七言绝句","c":["夭矫穷鳞江海姿，只今飞墨鬓如丝。","五云天远龙髯堕，尽作筼筜雨后枝。"]},{"t":"题赵仲穆擦痒马","f":"七言绝句","c":["啄疮乌去夕阳西，磨痒枯株振鬣嘶。","今日战场春草绿，相看谁濯锦障泥？"]},{"t":"题赵子昂兰","f":"七言绝句","c":["鸥波亭下楚香销，公子骑箕上泬寥。","纵是死灰芬酷烈，巫阳谁下九重招？"]},{"t":"题赵子固水仙","f":"七言绝句","c":["雨带风襟玉体寒，为谁解佩在江干？","金支翠钿那复得？","只愁归去便乘鸾。"]},{"t":"题墨山矾便面","f":"七言绝句","c":["一握方诸七里香，玉英如雪映春阳。","空山绝壑东风晚，底事湘累忘楚芳？"]},{"t":"题兰蕙便面","f":"七言绝句","c":["障面无嫌京洛尘，一丛兰蕙出冰轮。","只疑大地山河影，不照沅湘有逐臣。"]},{"t":"题熊自得丛竹便面","f":"七言绝句","c":["漪漪绿捲镜中天，元子何须苦恶圆？","万叶千枝繁不乱，化工消息尽无边。"]},{"t":"题李成枯木","f":"七言绝句","c":["谁如惜墨李营丘，屈铁交柯烟雨稠。","记得沧江龙出蛰，怒须捲雾拔山湫。"]},{"t":"题万竹图","f":"七言绝句","c":["远近阴晴玉万竿，渭川何在绿云寒。","砚坳飞墨如飞雨，白发萧郎仔细看。"]},{"t":"题王元章墨梅","f":"七言绝句","c":["旧时月色有谁歌，拔剑王郎鬓已皤。","惆怅春风旧词笔，南枝香少北枝多。"]},{"t":"题明雪窗兰","f":"七言绝句","c":["生公台石比双峨，两不为稀万不多。","兰蕙香销荆棘里，光风流转奈君何。"]},{"t":"题赵子昂兰石","f":"七言绝句","c":["捐玦孤臣万古愁，思君日夜水东流。","春风开遍闲桃李，却对青山泣楚囚。"]},{"t":"题柯敬仲梅竹图二首 其一","f":"七言绝句","c":["苔石相依葆岁寒，凭谁翠袖倚阑干？","玉文堂上萧萧雨，墨沈于今尚未乾。"]},{"t":"题柯敬仲梅竹图二首 其二","f":"七言绝句","c":["谁料丹丘不复生，眼眵长向墨踪明。","钓竿若拂珊瑚月，少为梅花住越城。"]},{"t":"题文与可竹","f":"七言绝句","c":["欲屈王郎作粲使，只因萧李与文侯。","尚有阴阴竹里馆，万竿玉立辋川秋。"]},{"t":"题岳家旧藏高彦敬云山图","f":"七言绝句","c":["千柱华榱淇渌堂，只今衰草野田荒。","空馀宝玩谁开阖？","一叠云山泪一行。"]},{"t":"题山水扇面","f":"七言绝句","c":["一握方诸镜里天，分明雁荡石城连。","仙人不患蓬壶小，便驻鸾笙五百年。"]},{"t":"送人","f":"七言绝句","c":["岁月蹉跎秋复春，轮囷瘿树不求伸。","斧斤何待秋零落，多是长松百尺身。"]},{"t":"题张叔厚白描麻姑像","f":"七言绝句","c":["狡狯仙人来自东，海波清浅日轮红。","易迁宫里飞霞佩，只在鸾笙一曲中。"]},{"t":"师子林八咏 其一 师子峰","f":"七言绝句","c":["天日耽耽师子岩，金毛闪日耀烟岚。","转身却向吴中吼，直与淩霄势并参。"]},{"t":"师子林八咏 其二 栖凤亭","f":"七言绝句","c":["翙翙朝阳孤凤凰，绿筠千尺起高冈。","何人解续卷阿颂？","戛玉鏦金作晚凉。"]},{"t":"师子林八咏 其三 飞虹桥","f":"七言绝句","c":["彩霓连蜷饮海空，老僧留作小飞虹。","舣舟因意吴江钓，苍雪吹凉满雨蓬。"]},{"t":"师子林八咏 其四 问梅訚","f":"七言绝句","c":["谩道龙驹踏杀人，梅花成实又逢春。","不因嚼碎无留核，谁为征蓬洗客尘？"]},{"t":"师子林八咏 其五 指柏轩","f":"七言绝句","c":["反覆神机老赵州，庭前柏树几经秋？","空林元自无枝叶，莫著祥鸾宿上头。"]},{"t":"师子林八咏 其六 玉鉴池","f":"七言绝句","c":["活水涓涓一鉴开，玉光射日瑩无埃。","临流照见行禅影，天际孤云蓦地来。"]},{"t":"师子林八咏 其七 立雪堂","f":"七言绝句","c":["少林山里雪漫漫，谁复将心与汝安？","近日师林寒彻骨，冰花吹满碧琅玕。"]},{"t":"师子林八咏 其八 卧云室","f":"七言绝句","c":["老随云卧不朝天，空影长当木榻穿。","便是绣衣传诏下，空山且复伴龙眠。"]},{"t":"西湖竹枝词二首 其一","f":"七言绝句","c":["岳王坟西是妾家，望郎不见见栖霞。","孤山若有奢华日，不种梅花种杏花。"]},{"t":"西湖竹枝词二首 其二","f":"七言绝句","c":["青青两点海门山，郎去贩鲜何日还？","潮水便如郎信息，江花恰是妾容颜。"]},{"t":"题倪云林画，次韵","f":"七言绝句","c":["云林雨过踏青阳，涧水溅溅老树苍。","不是砚坳云作阵，疏篁空自拂檐长。"]},{"t":"题陈惟允荆溪图","f":"七言绝句","c":["荆溪溪上首重回，岂意人间花劫灰？","只有斩蛟桥下水，可曾写入画图来？"]},{"t":"游仙词十首，并引 其一","f":"七言绝句","c":["金碧楼台瀛海东，娉婷仙子下瑶宫。","圣凡千古无穷事，都在鸾笙一曲中。"]},{"t":"游仙词十首，并引 其二","f":"七言绝句","c":["蔼蔼身中三素云，朝晖出海共氤氲。","桃霞沐雨轻匀面，柳浪含漪细织裙。"]},{"t":"游仙词十首，并引 其三","f":"七言绝句","c":["凤麟洲上水烟分，女伴同祠李少君。","点定易迁宫里籍，步虚携手踏红云。"]},{"t":"游仙词十首，并引 其四","f":"七言绝句","c":["煌煌珠树四时春，树影玲珑月满身。","理罢玉笙朝斗去，就中谁是避秦人？"]},{"t":"游仙词十首，并引 其五","f":"七言绝句","c":["云旗阿母降珠庭，母为双成欲授经。","尘世登真无要诀，药囊辛苦贮参苓。"]},{"t":"游仙词十首，并引 其六","f":"七言绝句","c":["才炊松屑饭胡麻，又见蟠桃一度花。","不为灵姝工服食，金盘那得枣如瓜？"]},{"t":"游仙词十首，并引 其七","f":"七言绝句","c":["窈窕溪真十二仙，灵犀分水夜长然。","珠宫每按皇人笔，点较青瑶第几篇？"]},{"t":"游仙词十首，并引 其八","f":"七言绝句","c":["宝髻骈云谁最高，花间行数旧栽桃。","笙洲月出星宫近，骑著神鱼舞翠涛。"]},{"t":"游仙词十首，并引 其九","f":"七言绝句","c":["紫皇亲驾按寰瀛，又见鲸波彻底清。","仙籍不能无谪降，尘缘敢恨有亏成？"]},{"t":"游仙词十首，并引 其十","f":"七言绝句","c":["欲采灵芝敢后期，游鱼千里费寻师。","不因悟得长生著，一局才终未了棋。"]},{"t":"赋巫峡云涛石屏","f":"七言绝句","c":["石理庚庚有至文，江涛鼓浪忽蒸云。","鬼神不露雕镂巧，那得阴阳一线分？"]},{"t":"题郑所南推篷竹卷","f":"七言绝句","c":["墨胎之墨死不化，固应此君长入画。","雨里推篷略见来，至今风节传天下。"]},{"t":"题赵子昂瓮牖图二首 其一","f":"七言绝句","c":["穷通由命不由人，结驷来窥瓮牖春。","富贵不淫贫贱乐，山青云白水粼粼。"]},{"t":"题赵子昂瓮牖图二首 其二","f":"七言绝句","c":["贫病无聊是老农，萧条门巷绝行踪。","画图不尽朋从意，凝望停云检宿舂。"]},{"t":"题赵魏公二帖","f":"七言绝句","c":["馀不溪边采白蘋，铁网珊瑚寸寸珍。","天上玉楼盛不住，虹光夜夜贯星辰。"]},{"t":"题曹云西山水","f":"七言绝句","c":["笔底江山不露锋，茅茨十尺倚长松。","采芝空谷归何晚？","知在晴云第几重？"]},{"t":"题郭天锡画二首 其一","f":"七言绝句","c":["飞墨来从海岳庵，春烟林麓是江南。","绿蘋洲渚闲鸥白，不著征人一解骖。"]},{"t":"题郭天锡画二首 其二","f":"七言绝句","c":["商颂何须曳履歌，江南山色砚池波。","长髯蘸得琳琅目，留作飞云在涧阿。"]},{"t":"赵子昂马图","f":"七言绝句","c":["王孙曾骑天厩驎，每忆龙驹便写真。","曹霸祇今那复得？","丹青剥落泪沾巾。"]},{"t":"题倪云林春山岚霭图","f":"七言绝句","c":["九龙峰上雨云乾，影落栖神涧水寒。","不是天机飞墨妙，何由写入画图看？"]},{"t":"采莲径","f":"七言绝句","c":["曲曲栏杆水殿凉，红绡扇底芰荷香。","按歌误触鸳鸯起，宫漏今宵分外凉。"]},{"t":"静安八咏 其一 赤乌碑","f":"七言绝句","c":["鼋趺螭首立重玄，沦落蛟龙百尺渊。","大手似闻皇象笔，老僧空记赤乌年。"]},{"t":"静安八咏 其二 陈桧","f":"七言绝句","c":["华飞三阁竟萧条，万木江南一夜凋。","独有祯明缨络桧，霜皮剥落气摩霄。"]},{"t":"静安八咏 其三 虾子禅","f":"七言绝句","c":["名缁神异肯炊沙，钵里蜿蜒喷浪花。","漂海不随虾国去，渡江还为老渔赊。"]},{"t":"静安八咏 其四 讲经台","f":"七言绝句","c":["东土高僧大梦还，讲经犹刺雨花台。","天龙去尽香云散，满地松阴长石苔。"]},{"t":"静安八咏 其五 沪渎垒","f":"七言绝句","c":["东吴内史晋长城，沪渎千年壁垒平。","莫向月明悲往事，即令沧海已尘生。"]},{"t":"静安八咏 其六 涌泉","f":"七言绝句","c":["涌泉亭子小冰壶，老蚌胎寒露溅珠。","只许鲛人弄明月，懒随龙叟泽焦枯。"]},{"t":"静安八咏 其七 芦子渡","f":"七言绝句","c":["吴淞古渡水如烟，十里芦花雪满天。","一苇可航还自许，老僧应不泛虚船。"]},{"t":"静安八咏 其八 绿云洞","f":"七言绝句","c":["长松钜竹翠敷腴，爽气清含雨露濡。","不异茅君主句曲，尚容元结隐猗玗。"]},{"t":"题萧翼赚兰亭图","f":"七言绝句","c":["已赚君亲走晋阳，老僧犹未识萧郎。","圣图本为天同大，谁谓桥山善守藏？"]},{"t":"题王叔明小画","f":"七言绝句","c":["幼舆丘壑未忘情，万叠青山照眼明。","儗向画图深处住，一檐灶日听松声。"]},{"t":"题倪元镇水竹居图","f":"七言绝句","c":["秋风潇飒满吴江，竹影飘飖落短窗。","堪爱倪迂清绝处，依微残墨本无双。"]},{"t":"题王渊花鸟轴","f":"七言绝句","c":["夜舒荷是若耶人，香散鸳鸯共影身。","一段柔情看未足，故教绮笔写来真。"]},{"t":"题郑思肖画兰","f":"七言绝句","c":["南冠江上哭湘累，泪著幽兰雨里枝。","不独苌弘血化碧，孤芳愁绝有谁知？"]},{"t":"书画舫小集分韵得春字","f":"七言古诗","c":["雪舫夜寒虹贯日，溪亭腊尽柳含春。","将军结发开全武，隐者逃名愧子真。","醉里都忘诗格峻，灯前但爱酒杯频。","芼羹青点沿墙荠，斫鲙冰飞出网鳞。","稽古尚能窥草圣，送穷端欲致钱神。","周南老去文章在，同谷歌终手脚皴。","擉鳖归来还自笑，闻鸡起舞意谁嗔。","盍簪岂料有今夕，明日桃源又问津。"]}]};